DG.put("ath-pakhyaan-charitr-likhyate/266",{"n":266,"title":null,"title_roman":null,"page":2085,"blocks":[{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2085},{"type":"verse","number":[1],"number_text":"੧।","page":2085,"lines":[{"gurmukhi":"ਸੁਮਤਿ ਸੈਨ ਇਕ ਨ੍ਰਿਪਤਿ ਸੁਨਾ ਬਰ। ਦੁਤਿਯ ਦਿਵਾਕਰ ਕਿਧੌ ਕਿਰਨਿਧਰ।","roman":"Sumti sain ik nripti sunaa bar | dutiy divaakar kidhau kirnidhar |","meaning_en":"","page":2085},{"gurmukhi":"ਸਮਰ ਮਤੀ ਰਾਨੀ ਗ੍ਰਿਹ ਤਾ ਕੇ। ਸੁਰੀ ਆਸੁਰੀ ਸਮ ਨਹਿ ਜਾ ਕੇ। ੧।","roman":"Samar matee raanee grih taa ke | suree aasuree sam nahi jaa ke | 1 |","meaning_en":"","page":2085}]},{"type":"verse","number":[2],"number_text":"੨।","page":2085,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਰਨਖੰਭ ਕਲਾ ਦੁਹਿਤਾ ਤਿਹ। ਜੀਤਿ ਲਈ ਸਸਿ ਅੰਸ ਕਲਾ ਜਿਹ।","roman":"Sree rankhanbh kalaa duhitaa tih | jeeti laee sasi ans kalaa jih |","meaning_en":"","page":2085},{"gurmukhi":"ਨਿਰਖਿ ਭਾਨ ਜਿਹਾ ਪ੍ਰਭਾ ਰਹਤ ਦਬਿ। ਸੁਰੀ ਆਸੁਰਿਨ ਕੀ ਨਹਿ ਸਮ ਛਬਿ। ੨।","roman":"Nirkhi bhaan jihaa prabhaa rahat dabi | suree aasurin kee nahi sam chhabi | 2 |","meaning_en":"","page":2085}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2085},{"type":"verse","number":[3],"number_text":"੩।","page":2085,"lines":[{"gurmukhi":"ਤਰੁਨਿ ਭਈ ਤਰੁਨੀ ਜਬੈ ਅਧਿਕ ਸੁਖਨ ਕੇ ਸੰਗ।","roman":"Taruni bhaee tarunee jabai adhik sukhan ke sang |","meaning_en":"","page":2085},{"gurmukhi":"ਲਰਿਕਾਪਨ ਮਿਟਿ ਜਾਤ ਭਯੋ ਦੁੰਦਭਿ ਦਿਯੋ ਅਨੰਗ। ੩।","roman":"Larikaapan miti jaat bhayo dundbhi diyo anang | 3 |","meaning_en":"","page":2085}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2085},{"type":"verse","number":[4],"number_text":"੪।","page":2085,"lines":[{"gurmukhi":"ਚਾਰਿ ਭ੍ਰਾਤ ਤਾ ਕੇ ਬਲਵਾਨਾ। ਸੂਰਬੀਰ ਸਭ ਸਸਤ੍ਰ ਨਿਧਾਨਾ।","roman":"Chaari bhraat taa ke balvaanaa | soorbeer sabh sasatr nidhaanaa |","meaning_en":"","page":2085},{"gurmukhi":"ਤੇਜਵਾਨ ਦੁਤਿਮਾਨ ਅਤੁਲ ਬਲ। ਅਰਿ ਅਨੇਕ ਜੀਤੇ ਜਿਹ ਦਲਿ ਮਲਿ। ੪।","roman":"Tejvaan dutimaan atul bal | ari anek jeete jih dali mali | 4 |","meaning_en":"","page":2085}]},{"type":"verse","number":[5],"number_text":"੫।","page":2085,"lines":[{"gurmukhi":"ਸਾਰਦੂਲ ਧੁਜ ਨਾਹਰ ਧੁਜ ਭਨ। ਸਿੰਘ ਕੇਤੁ ਹਰਿ ਕੇਤੁ ਮਹਾ ਮਨ।","roman":"Saardool dhuj naahar dhuj bhan | singh ketu hari ketu mahaa man |","meaning_en":"","page":2085},{"gurmukhi":"ਚਾਰੌ ਸੂਰਬੀਰ ਬਲਵਾਨਾ। ਮਾਨਤ ਸਤ੍ਰੁ ਸਕਲ ਜਿਹ ਆਨਾ। ੫।","roman":"Chaarau soorbeer balvaanaa | maanat satru sakal jih aanaa | 5 |","meaning_en":"","page":2085}]},{"type":"verse","number":[6],"number_text":"੬।","page":2085,"lines":[{"gurmukhi":"ਚਾਰੌ ਕੁਅਰਿ ਪੜਨ ਕੇ ਕਾਜਾ। ਦਿਜ ਇਕ ਬੋਲਿ ਪਠਾਯੋ ਰਾਜਾ।","roman":"Chaarau kuari paran ke kaajaa | dij ik boli pathaayo raajaa |","meaning_en":"","page":2085},{"gurmukhi":"ਭਾਖ੍ਯਾਦਿਕ ਬ੍ਯਾਕਰਨ ਪੜੇ ਜਿਨ। ਔਗਾਹਨ ਸਭ ਕਿਯ ਪੁਰਾਨ ਤਿਨ। ੬।","roman":"Bhaakhyaadik byaakran pare jin | augaahan sabh kiy puraan tin | 6 |","meaning_en":"","page":2085}]},{"type":"verse","number":[7],"number_text":"੭।","page":2085,"lines":[{"gurmukhi":"ਅਧਿਕ ਦਰਬ ਨ੍ਰਿਪ ਬਰ ਤਿਹ ਦੀਯਾ। ਬਿਬਿਧ ਬਿਧਨ ਕਰਿ ਆਦਰ ਕੀਯਾ।","roman":"Adhik darab nrip bar tih deeyaa | bibidh bidhan kari aadar keeyaa |","meaning_en":"","page":2085},{"gurmukhi":"ਸੁਤਾ ਸਹਿਤ ਸੌਪੇ ਸੁਤ ਤਿਹ ਘਰ। ਕਛੁ ਬਿਦ੍ਯਾ ਦਿਜਿ ਦੇਹੁ ਕ੍ਰਿਪਾ ਕਰਿ। ੭।","roman":"Sutaa sahit saupe sut tih ghar | kachhu bidyaa diji dehu kripaa kari | 7 |","meaning_en":"","page":2085}]},{"type":"verse","number":[8],"number_text":"੮।","page":2085,"lines":[{"gurmukhi":"ਜਬ ਤੇ ਤਹ ਪੜਬੇ ਕਹ ਆਵੈ। ਅਪਨੋ ਬਿਪ ਕਹ ਸੀਸ ਝੁਕਾਵੈ।","roman":"Jab te tah parbe kah aavai | apno bip kah sees jhukaavai |","meaning_en":"","page":2085},{"gurmukhi":"ਜੋ ਸਿਖ੍ਯਾ ਦਿਜ ਦੇਤ ਸੁ ਲੇਹੀ। ਅਮਿਤ ਦਰਬ ਪੰਡਿਤ ਕਹ ਦੇਹੀ। ੮।","roman":"Jo sikhyaa dij det su lehee | amit darab pandit kah dehee | 8 |","meaning_en":"","page":2085}]},{"type":"verse","number":[9],"number_text":"੯।","page":2085,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਕੁਅਰਿ ਅਗਮਨੋ ਗਈ। ਦਿਜ ਕਹ ਸੀਸ ਝੁਕਾਵਤ ਭਈ।","roman":"Ik din kuari agamno gaee | dij kah sees jhukaavat bhaee |","meaning_en":"","page":2085},{"gurmukhi":"ਸਾਲਿਗ੍ਰਾਮ ਪੂਜਤ ਥਾ ਦਿਜਬਰ। ਭਾਤਿ ਭਾਤਿ ਤਿਹ ਸੀਸ ਨ੍ਯਾਇ ਕਰਿ। ੯।","roman":"Saaligraam poojat thaa dijbar | bhaati bhaati tih sees nyaai kari | 9 |","meaning_en":"","page":2085}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":2087,"lines":[{"gurmukhi":"ਤਾ ਕੌ ਨਿਰਖਿ ਕੁਅਰਿ ਮੁਸਕਾਨੀ। ਸੋ ਪ੍ਰਤਿਮਾ ਪਾਹਨ ਪਹਿਚਾਨੀ।","roman":"Taa kau nirkhi kuari muskaanee | so pratimaa paahan pahichaanee |","meaning_en":"","page":2087},{"gurmukhi":"ਤਾਹਿ ਕਹਾ ਪੂਜਤ ਕਿਹ ਨਮਿਤਿਹ। ਸਿਰ ਨਾਵਤ ਕਰ ਜੋਰਿ ਕਾਜ ਜਿਹ। ੧੦।","roman":"Taahi kahaa poojat kih namitih | sir naavat kar jori kaaj jih | 10 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2087},{"type":"verse","number":[11],"number_text":"੧੧।","page":2087,"lines":[{"gurmukhi":"ਸਾਲਗ੍ਰਾਮ ਠਾਕੁਰ ਏ ਬਾਲਾ। ਪੂਜਤ ਜਿਨੈ ਬਡੇ ਨਰਪਾਲਾ।","roman":"Saalgraam thaakur e baalaa | poojat jinai bade narpaalaa |","meaning_en":"","page":2087},{"gurmukhi":"ਤੈ ਅਗ੍ਯਾਨ ਇਹ ਕਹਾ ਪਛਾਨੈ। ਪਰਮੇਸ੍ਵਰ ਕਹ ਪਾਹਨ ਜਾਨੈ। ੧੧।","roman":"Tai agyaan ih kahaa pachhaanai | parmesvar kah paahan jaanai | 11 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਸੁਤ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਸੁਤ ਬਾਚ","roman":"Raajaa sut baach","meaning_en":"","page":2087},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":2087},{"type":"verse","number":[12],"number_text":"੧੨।","page":2087,"lines":[{"gurmukhi":"ਤਾਹਿ ਪਛਾਨਤ ਹੈ ਨ ਮਹਾ ਜੜ ਜਾ ਕੋ ਪ੍ਰਤਾਪ ਤਿਹੂੰ ਪੁਰ ਮਾਹੀ।","roman":"Taahi pachhaanat hai na mahaa jar jaa ko prataap tihoon pur maahee |","meaning_en":"","page":2087},{"gurmukhi":"ਪੂਜਤ ਹੈ ਪ੍ਰਭੁ ਕੈ ਤਿਸ ਕੌ ਜਿਨ ਕੇ ਪਰਸੇ ਪਰਲੋਕ ਪਰਾਹੀ।","roman":"Poojat hai prabhu kai tis kau jin ke parse parlok paraahee |","meaning_en":"","page":2087},{"gurmukhi":"ਪਾਪ ਕਰੋ ਪਰਮਾਰਥ ਕੈ ਜਿਹ ਪਾਪਨ ਤੇ ਅਤਿ ਪਾਪ ਡਰਾਹੀ।","roman":"Paap karo parmaarath kai jih paapan te ati paap daraahee |","meaning_en":"","page":2087},{"gurmukhi":"ਪਾਇ ਪਰੋ ਪਰਮੇਸ੍ਵਰ ਕੇ ਪਸੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਰ ਨਾਹੀ। ੧੨।","roman":"Paai paro parmesvar ke pasu paahan mai parmesvar naahee | 12 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"","page":2087},{"type":"verse","number":[13],"number_text":"੧੩।","page":2087,"lines":[{"gurmukhi":"ਜੀਵਨ ਮੈ ਜਲ ਮੈ ਥਲ ਮੈ ਸਭ ਰੂਪਨ ਮੈ ਸਭ ਭੂਪਨ ਮਾਹੀ।","roman":"Jeevan mai jal mai thal mai sabh roopan mai sabh bhoopan maahee |","meaning_en":"","page":2087},{"gurmukhi":"ਸੂਰਜ ਮੈ ਸਸਿ ਮੈ ਨਭ ਮੈ ਜਹ ਹੇਰੌ ਤਹਾ ਚਿਤ ਲਾਇ ਤਹਾ ਹੀ।","roman":"Sooraj mai sasi mai nabh mai jah herau tahaa chit laai tahaa hee |","meaning_en":"","page":2087},{"gurmukhi":"ਪਾਵਕ ਮੈ ਅਰੁ ਪੌਨ ਹੂੰ ਮੈ ਪ੍ਰਿਥਵੀ ਤਲ ਮੈ ਸੁ ਕਹਾ ਨਹਿ ਜਾਹੀ।","roman":"Paavak mai aru paun hoon mai prithvee tal mai su kahaa nahi jaahee |","meaning_en":"","page":2087},{"gurmukhi":"ਬ੍ਯਾਪਕ ਹੈ ਸਭ ਹੀ ਕੇ ਬਿਖੈ ਕਛੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਵਰ ਨਾਹੀ। ੧੩।","roman":"Byaapak hai sabh hee ke bikhai kachhu paahan mai parmesvavar naahee | 13 |","meaning_en":"","page":2087}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":2087,"lines":[{"gurmukhi":"ਕਾਗਜ ਦੀਪ ਸਭੈ ਕਰਿ ਕੈ ਅਰੁ ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਕੀ ਮਸੁ ਕੈਯੈ।","roman":"Kaagaj deep sabhai kari kai aru saat samundran kee masu kaiyai |","meaning_en":"","page":2087},{"gurmukhi":"ਕਾਟਿ ਬਨਾਸਪਤੀ ਸਿਗਰੀ ਲਿਖਬੇ ਹੂੰ ਕੌ ਲੇਖਨਿ ਕਾਜ ਬਨੈਯੈ।","roman":"Kaati banaasaptee sigree likhbe hoon kau lekhni kaaj banaiyai |","meaning_en":"","page":2087},{"gurmukhi":"ਸਾਰਸ੍ਵਤੀ ਬਕਤਾ ਕਰਿ ਕੈ ਸਭ ਜੀਵਨ ਤੇ ਜੁਗ ਸਾਠਿ ਲਿਖੈਯੈ।","roman":"Saarsvatee baktaa kari kai sabh jeevan te jug saathi likhaiyai |","meaning_en":"","page":2087},{"gurmukhi":"ਜੋ ਪ੍ਰਭੁ ਪਾਯੁਤ ਹੈ ਨਹਿ ਕੈਸੇ ਹੂੰ ਸੋ ਜੜ ਪਾਹਨ ਮੌ ਠਹਰੈਯੈ।੧੪।","roman":"Jo prabhu paayut hai nahi kaise hoon so jar paahan mau thahraiyai | 14 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2087},{"type":"verse","number":[15],"number_text":"੧੫।","page":2087,"lines":[{"gurmukhi":"ਏ ਜਨ ਭੇਵ ਨ ਹਰਿ ਕੋ ਪਾਵੈ। ਪਾਹਨ ਮੈ ਹਰਿ ਕੌ ਠਹਰਾਵੈ।","roman":"E jan bhev na hari ko paavai | paahan mai hari kau thahraavai |","meaning_en":"","page":2087},{"gurmukhi":"ਜਿਹ ਕਿਹ ਬਿਧਿ ਲੋਗਨ ਭਰਮਾਹੀ। ਗ੍ਰਿਹ ਕੋ ਦਰਬੁ ਲੂਟਿ ਲੈ ਜਾਹੀ। ੧੫।","roman":"Jih kih bidhi logan bharmaahee | grih ko darbu looti lai jaahee | 15 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2087},{"type":"verse","number":[16],"number_text":"੧੬।","page":2087,"lines":[{"gurmukhi":"ਜਗ ਮੈ ਆਪੁ ਕਹਾਵਈ ਪੰਡਿਤ ਸੁਘਰ ਸੁਚੇਤ।","roman":"Jag mai aapu kahaavaee pandit sughar suchet |","meaning_en":"","page":2087},{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰੈ ਯਾ ਤੇ ਲਗਤ ਅਚੇਤ। ੧੬।","roman":"Paahan kee poojaa karai yaa te lagat achet | 16 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2087},{"type":"verse","number":[17],"number_text":"੧੭।","page":2087,"lines":[{"gurmukhi":"ਚਿਤ ਭੀਤਰ ਆਸਾ ਧਨ ਧਾਰੈ। ਸਿਵ ਸਿਵ ਸਿਵ ਮੁਖ ਤੇ ਉਚਾਰੈ।","roman":"Chit bheetar aasaa dhan dhaarai | siv siv siv mukh te uchaarai |","meaning_en":"","page":2087},{"gurmukhi":"ਅਧਿਕ ਡਿੰਭ ਕਰਿ ਜਗਿ ਦਿਖਾਵੈ। ਦ੍ਵਾਰ ਦ੍ਵਾਰ ਮਾਗਤ ਨ ਲਜਾਵੈ। ੧੭।","roman":"Adhik dinbh kari jagi dikhaavai | dvaar dvaar maagat na lajaavai | 17 |","meaning_en":"","page":2087}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2089},{"type":"verse","number":[18],"number_text":"੧੮।","page":2089,"lines":[{"gurmukhi":"ਨਾਕ ਮੂੰਦਿ ਕਰਿ ਚਾਰਿ ਘਰੀ ਠਾਢੇ ਰਹੈ।","roman":"Naak moondi kari chaari gharee thaadhe rahai |","meaning_en":"","page":2089},{"gurmukhi":"ਸਿਵ ਸਿਵ ਸਿਵ ਹ੍ਵੈ ਏਕ ਚਰਨ ਇਸਥਿਤ ਕਹੈ।","roman":"Siv siv siv hvai ek charan isthit kahai |","meaning_en":"","page":2089},{"gurmukhi":"ਜੋ ਕੋਊ ਪੈਸਾ ਏਕ ਦੇਤ ਕਰਿ ਆਇ ਕੈ।","roman":"Jo ko'oo paisaa ek det kari aai kai |","meaning_en":"","page":2089},{"gurmukhi":"ਹੋ ਦਾਤਨ ਲੇਤ ਉਠਾਇ ਸਿਵਹਿ ਬਿਸਰਾਇ ਕੈ। ੧੮।","roman":"Ho daatan let uthaai sivhi bisraai kai | 18 |","meaning_en":"","page":2089}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":2089},{"type":"verse","number":[19],"number_text":"੧੯।","page":2089,"lines":[{"gurmukhi":"ਔਰਨੁਪਦੇਸ ਕਰੈ ਆਪੁ ਧ੍ਯਾਨ ਕੌ ਨ ਧਰੈ","roman":"Aurnupdes karai aapu dhyaan kau na dharai","meaning_en":"","page":2089},{"gurmukhi":"ਲੋਗਨ ਕੌ ਸਦਾ ਤ੍ਯਾਗ ਧਨ ਕੋ ਦ੍ਰਿੜਾਤ ਹੈ।","roman":"Logan kau sadaa tyaag dhan ko driraat hai |","meaning_en":"","page":2089},{"gurmukhi":"ਤੇਹੀ ਧਨ ਲੋਭ ਊਚ ਨੀਚਨ ਕੇ ਦ੍ਵਾਰ ਦ੍ਵਾਰ","roman":"Tehee dhan lobh ooch neechan ke dvaar dvaar","meaning_en":"","page":2089},{"gurmukhi":"ਲਾਜ ਕੌ ਤਿਯਾਗ ਜੇਹੀ ਤੇਹੀ ਪੈ ਘਿਘਾਤ ਹੈ।","roman":"Laaj kau tiyaag jehee tehee pai ghighaat hai |","meaning_en":"","page":2089},{"gurmukhi":"ਕਹਤ ਪਵਿਤ੍ਰ ਹਮ ਰਹਤ ਅਪਵਿਤ੍ਰ ਖਰੇ","roman":"Kahat pavitr ham rahat apvitr khare","meaning_en":"","page":2089},{"gurmukhi":"ਚਾਕਰੀ ਮਲੇਛਨ ਕੀ ਕੈਕੈ ਟੂਕ ਖਾਤ ਹੈ।","roman":"Chaakree malechhan kee kaikai took khaat hai |","meaning_en":"","page":2089},{"gurmukhi":"ਬਡੇ ਅਸੰਤੋਖੀ ਹੈ ਕਹਾਵਤ ਸੰਤੋਖੀ ਮਹਾ","roman":"Bade asantokhee hai kahaavat santokhee mahaa","meaning_en":"","page":2089},{"gurmukhi":"ਏਕ ਦ੍ਵਾਰ ਛਾਡਿ ਮਾਗਿ ਦ੍ਵਾਰੇ ਦ੍ਵਾਰ ਜਾਤ ਹੈ। ੧੯।","roman":"Ek dvaar chhaadi maagi dvaare dvaar jaat hai | 19 |","meaning_en":"","page":2089}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2089,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੇ ਸਿਵ ਬਨਾਏ ਪੂਜਿ ਕੈ ਬਹਾਇ ਆਏ","roman":"Maatee ke siv banaae pooji kai bahaai aae","meaning_en":"","page":2089},{"gurmukhi":"ਆਇ ਕੈ ਬਨਾਏ ਫੇਰਿ ਮਾਟੀ ਕੇ ਸੁਧਾਰਿ ਕੈ।","roman":"Aai kai banaae pheri maatee ke sudhaari kai |","meaning_en":"","page":2089},{"gurmukhi":"ਤਾ ਕੇ ਪਾਇ ਪਰਿਯੋ ਮਾਥੋ ਘਰੀ ਦ੍ਵੈ ਰਗਰਿਯੋ","roman":"Taa ke paai pariyo maatho gharee dvai ragriyo","meaning_en":"","page":2089},{"gurmukhi":"ਐ ਰੇ ਤਾ ਮੈ ਕਹਾ ਹੈ ਰੇ ਦੈ ਹੈ ਤੋਹਿ ਕੌ ਬਿਚਾਰਿ ਕੈ।","roman":"Ai re taa mai kahaa hai re dai hai tohi kau bichaari kai |","meaning_en":"","page":2089},{"gurmukhi":"ਲਿੰਗ ਕੀ ਤੂ ਪੂਜਾ ਕਰੈ ਸੰਭੁ ਜਾਨਿ ਪਾਇ ਪਰੈ","roman":"Ling kee too poojaa karai sanbhu jaani paai parai","meaning_en":"","page":2089},{"gurmukhi":"ਸੋਈ ਅੰਤ ਦੈਹੈ ਤੇਰੇ ਕਰ ਮੈ ਨਿਕਾਰਿ ਕੈ।","roman":"Soee ant daihai tere kar mai nikaari kai |","meaning_en":"","page":2089},{"gurmukhi":"ਦੁਹਿਤਾ ਕੌ ਦੈਹੈ ਕੀ ਤੂ ਆਪਨ ਖਬੈ ਹੈ ਤਾ ਕੌ","roman":"Duhitaa kau daihai kee too aapan khabai hai taa kau","meaning_en":"","page":2089,"flags":[{"code":"ੇੈ","reason":"ੇ and ੈ typed on one letter; one covers the other, printed as ੈ"}]},{"gurmukhi":"ਯੌ ਹੀ ਤੋਹਿ ਮਾਰਿ ਹੈ ਰੇ ਸਦਾ ਸਿਵ ਖ੍ਵਾਰਿ ਕੈ। ੨੦।","roman":"Yau hee tohi maari hai re sadaa siv khvaari kai | 20 |","meaning_en":"","page":2089}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"","page":2089},{"type":"verse","number":[21],"number_text":"੨੧।","page":2089,"lines":[{"gurmukhi":"ਪਾਹਨ ਕੌ ਸਿਵ ਤੂ ਜੋ ਕਹੈ ਪਸੁ ਯਾ ਤੇ ਕਛੁ ਤੁਹਿ ਹਾਥ ਨ ਐ ਹੈ।","roman":"Paahan kau siv too jo kahai pasu yaa te kachhu tuhi haath na ai hai |","meaning_en":"","page":2089},{"gurmukhi":"ਤ੍ਰੈਯਕ ਜੋਨਿ ਜੁ ਆਪੁ ਪਰਾ ਹਸਿ ਕੈ ਤੁਹਿ ਕੋ ਕਹੁ ਕਾ ਬਰੁ ਦੈ ਹੈ।","roman":"Traiyak joni ju aapu paraa hasi kai tuhi ko kahu kaa baru dai hai |","meaning_en":"","page":2089},{"gurmukhi":"ਆਪਨ ਸੋ ਕਰਿ ਹੈ ਕਬਹੂੰ ਤੁਹਿ ਪਾਹਨ ਕੀ ਪਦਵੀ ਤਬ ਪੈ ਹੈ।","roman":"Aapan so kari hai kabhoon tuhi paahan kee padvee tab pai hai |","meaning_en":"","page":2089},{"gurmukhi":"ਜਾਨੁ ਰੇ ਜਾਨੁ ਅਜਾਨ ਮਹਾ ਫਿਰਿ ਜਾਨ ਗਈ ਕਛੁ ਜਾਨਿ ਨ ਜੈ ਹੈ। ੨੧।","roman":"Jaanu re jaanu ajaan mahaa phiri jaan gaee kachhu jaani na jai hai | 21 |","meaning_en":"","page":2089}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":2089,"lines":[{"gurmukhi":"ਬੈਸ ਗਈ ਲਰਿਕਾਪਨ ਮੋ ਤਰੁਨਾਪਨ ਮੈ ਨਹਿ ਨਾਮ ਲਯੋ ਰੇ।","roman":"Bais gaee larikaapan mo tarunaapan mai nahi naam layo re |","meaning_en":"","page":2089},{"gurmukhi":"ਔਰਨ ਦਾਨ ਕਰਾਤ ਰਹਾ ਕਰ ਆਪ ਉਠਾਇ ਨ ਦਾਨ ਦਯੋ ਰੇ।","roman":"Auran daan karaat rahaa kar aap uthaai na daan dayo re |","meaning_en":"","page":2089},{"gurmukhi":"ਪਾਹਨ ਕੋ ਸਿਰ ਨ੍ਯਾਤਨ ਤੈ ਪਰਮੇਸ੍ਵਰ ਕੌ ਸਿਰ ਨ੍ਯਾਤ ਭਯੋ ਰੇ।","roman":"Paahan ko sir nyaatan tai parmesvar kau sir nyaat bhayo re |","meaning_en":"","page":2089},{"gurmukhi":"ਕਾਮਹਿ ਕਾਮ ਫਸਾ ਘਰ ਕੇ ਜੜ ਕਾਲਹਿ ਕਾਲ ਕੈ ਕਾਲ ਗਯੋ ਰੇ। ੨੨।","roman":"Kaamhi kaam phasaa ghar ke jar kaalhi kaal kai kaal gayo re | 22 |","meaning_en":"","page":2089}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2089,"lines":[{"gurmukhi":"ਦ੍ਵੈਕ ਪੁਰਾਨਨ ਕੌ ਪੜਿ ਕੈ ਤੁਮ ਫੂਲਿ ਗਏ ਦਿਜ ਜੂ ਜਿਯ ਮਾਹੀ।","roman":"Dvaik puraanan kau pari kai tum phooli gae dij joo jiy maahee |","meaning_en":"","page":2089},{"gurmukhi":"ਸੋ ਨ ਪੁਰਾਨ ਪੜਾ ਜਿਹ ਕੇ ਇਹ ਠੌਰ ਪੜੇ ਸਭ ਪਾਪ ਪਰਾਹੀ।।","roman":"So na puraan paraa jih ke ih thaur pare sabh paap paraahee ||","meaning_en":"","page":2089},{"gurmukhi":"ਡਿੰਭ ਦਿਖਾਇ ਕਰੋ ਤਪਸਾ ਦਿਨ ਰੈਨਿ ਬਸੈ ਜਿਯਰਾ ਧਨ ਮਾਹੀ।","roman":"Dinbh dikhaai karo tapsaa din raini basai jiyraa dhan maahee |","meaning_en":"","page":2089},{"gurmukhi":"ਮੂਰਖ ਲੋਗ ਪ੍ਰਮਾਨ ਕਰੈ ਇਨ ਬਾਤਨ ਕੌ ਹਮ ਮਾਨਤ ਨਾਹੀ। ੨੩।","roman":"Moorakh log pramaan karai in baatan kau ham maanat naahee | 23 |","meaning_en":"","page":2089}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2091,"lines":[{"gurmukhi":"ਕਾਹੇ ਕੋ ਕਾਜ ਕਰੋ ਇਤਨੀ ਤੁਮ ਪਾਹਨ ਕੋ ਕਿਹ ਕਾਜ ਪੁਜਾਵੋ।","roman":"Kaahe ko kaaj karo itnee tum paahan ko kih kaaj pujaavo |","meaning_en":"","page":2091},{"gurmukhi":"ਕਾਹੇ ਕੋ ਡਿੰਭ ਕਰੋ ਜਗ ਮੈ ਇਹ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਗਵਾਵੋ।","roman":"Kaahe ko dinbh karo jag mai ih lok gayo parlok gavaavo |","meaning_en":"","page":2091},{"gurmukhi":"ਝੂਠੇ ਨ ਮੰਤ੍ਰ ਉਪਦੇਸ ਕਰੋ ਜੋਊ ਚਾਹਤ ਹੋ ਧਨ ਲੌ ਹਰਖਾਵੋ।","roman":"Jhoothe na mantr updes karo jo'oo chaahat ho dhan lau harkhaavo |","meaning_en":"","page":2091},{"gurmukhi":"ਰਾਜ ਕੁਮਾਰਨ ਮੰਤ੍ਰ ਦਿਯੋ ਸੁ ਦਿਯੋ ਬਹੁਰੌ ਹਮ ਕੌ ਨ ਸਿਖਾਵੋ। ੨੪।","roman":"Raaj kumaaran mantr diyo su diyo bahurau ham kau na sikhaavo | 24 |","meaning_en":"","page":2091}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2091},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2091},{"type":"verse","number":[25],"number_text":"੨੫।","page":2091,"lines":[{"gurmukhi":"ਕਹਾ ਬਿਪ੍ਰ ਸੁਨੁ ਰਾਜ ਦੁਲਾਰੀ। ਤੈ ਸਿਵ ਕੀ ਮਹਿਮਾ ਨ ਬਿਚਾਰੀ।","roman":"Kahaa bipr sunu raaj dulaaree | tai siv kee mahimaa na bichaaree |","meaning_en":"","page":2091},{"gurmukhi":"ਬ੍ਰਹਮਾ ਬਿਸਨ ਰੁਦ੍ਰ ਜੂ ਦੇਵਾ। ਇਨ ਕੀ ਸਦਾ ਕੀਜਿਯੈ ਸੇਵਾ। ੨੫।","roman":"Brahmaa bisan rudr joo devaa | in kee sadaa keejiyai sevaa | 25 |","meaning_en":"","page":2091}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2091,"lines":[{"gurmukhi":"ਤੈ ਯਾ ਕੇ ਭੇਵਹਿ ਨ ਪਛਾਨੈ। ਮਹਾ ਮੂੜ ਇਹ ਭਾਤਿ ਬਖਾਨੈ।","roman":"Tai yaa ke bhevhi na pachhaanai | mahaa moor ih bhaati bakhaanai |","meaning_en":"","page":2091},{"gurmukhi":"ਇਨ ਕੋ ਪਰਮ ਪੁਰਾਤਨ ਜਾਨਹੁ। ਪਰਮ ਪੁਰਖ ਮਨ ਮਹਿ ਪਹਿਚਾਨਹੁ। ੨੬।","roman":"In ko param puraatan jaanhu | param purakh man mahi pahichaanhu | 26 |","meaning_en":"","page":2091}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2091,"lines":[{"gurmukhi":"ਹਮ ਹੈ ਕੁਅਰਿ ਬਿਪ੍ਰ ਬ੍ਰਤ ਧਾਰੀ। ਊਚ ਨੀਚ ਸਭ ਕੇ ਹਿਤਕਾਰੀ।","roman":"Ham hai kuari bipr brat dhaaree | ooch neech sabh ke hitkaaree |","meaning_en":"","page":2091},{"gurmukhi":"ਜਿਸੀ ਕਿਸੀ ਕਹ ਮੰਤ੍ਰ ਸਿਖਾਵੈ। ਮਹਾ ਕ੍ਰਿਪਨ ਤੇ ਦਾਨ ਕਰਾਵੈ। ੨੭।","roman":"Jisee kisee kah mantr sikhaavai | mahaa kripan te daan karaavai | 27 |","meaning_en":"","page":2091}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2091},{"type":"verse","number":[28],"number_text":"੨੮।","page":2091,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਦੇਤ ਸਿਖ ਅਪਨ ਕਰਤ ਹਿਤ। ਜ੍ਯੋ ਤ੍ਯੋ ਭੇਟ ਲੈਤ ਤਾ ਤੇ ਬਿਤ।","roman":"Mantr det sikh apan karat hit | jyo tyo bhet lait taa te bit |","meaning_en":"","page":2091},{"gurmukhi":"ਸਤਿ ਬਾਤ ਤਾ ਕਹ ਨ ਸਿਖਾਵਹੁ। ਤਾਹਿ ਲੋਕ ਪਰਲੋਕ ਗਵਾਵਹੁ। ੨੮।","roman":"Sati baat taa kah na sikhaavhu | taahi lok parlok gavaavhu | 28 |","meaning_en":"","page":2091}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2091,"lines":[{"gurmukhi":"ਸੁਨਹੁ ਬਿਪ ਤੁਮ ਮੰਤ੍ਰ ਦੇਤ ਜਿਹ। ਲੂਟਿ ਲੇਤ ਤਿਹ ਘਰ ਬਿਧਿ ਜਿਹ ਕਿਹ।","roman":"Sunhu bip tum mantr det jih | looti let tih ghar bidhi jih kih |","meaning_en":"","page":2091},{"gurmukhi":"ਤਾ ਕਹ ਕਛੂ ਗ੍ਯਾਨ ਨਹਿ ਆਵੈ। ਮੂਰਖ ਅਪਨਾ ਮੂੰਡ ਮੁੰਡਾਵੈ। ੨੯।","roman":"Taa kah kachhoo gyaan nahi aavai | moorakh apnaa moond mundaavai | 29 |","meaning_en":"","page":2091}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2091,"lines":[{"gurmukhi":"ਤਿਹ ਤੁਮ ਕਹੁ ਮੰਤ੍ਰ ਸਿਧਿ ਹ੍ਵੈਹੈ। ਮਹਾਦੇਵ ਤੋ ਕੌ ਬਰੁ ਦੈ ਹੈ।","roman":"Tih tum kahu mantr sidhi hvaihai | mahaadev to kau baru dai hai |","meaning_en":"","page":2091},{"gurmukhi":"ਜਬ ਤਾ ਤੇ ਨਹਿ ਹੋਤ ਮੰਤ੍ਰ ਸਿਧਿ। ਤਬ ਤੁਮ ਬਚਨ ਕਹਤ ਹੌ ਇਹ ਬਿਧਿ। ੩੦।","roman":"Jab taa te nahi hot mantr sidhi | tab tum bachan kahat hau ih bidhi | 30 |","meaning_en":"","page":2091}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2091,"lines":[{"gurmukhi":"ਕਛੂ ਕੁਕ੍ਰਿਯਾ ਤੁਮਤੇ ਭਯੋ। ਤਾ ਤੇ ਦਰਸ ਨ ਸਿਵ ਜੂ ਦਯੋ।","roman":"Kachhoo kukriyaa tumte bhayo | taa te daras na siv joo dayo |","meaning_en":"","page":2091},{"gurmukhi":"ਅਬ ਤੈ ਪੁੰਨ੍ਯ ਦਾਨ ਦਿਜ ਕਰ ਰੇ। ਪੁਨਿ ਸਿਵ ਕੇ ਮੰਤ੍ਰਹਿ ਅਨੁਸਰੁ ਰੇ। ੩੧।","roman":"Ab tai punny daan dij kar re | puni siv ke mantrahi anusru re | 31 |","meaning_en":"","page":2091}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":2091,"lines":[{"gurmukhi":"ਉਲਟੋ ਡੰਡ ਤਿਸੀ ਤੇ ਲੇਹੀ। ਪੁਨਿ ਤਿਹ ਮੰਤ੍ਰ ਰੁਦ੍ਰ ਕੋ ਦੇਹੀ।","roman":"Ulto dand tisee te lehee | puni tih mantr rudr ko dehee |","meaning_en":"","page":2091},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਾ ਕੌ ਭਟਕਾਵੈ। ਅੰਤ ਬਾਰ ਇਮਿ ਭਾਖ ਸੁਨਾਵੈ। ੩੨।","roman":"Bhaati bhaati taa kau bhatkaavai | ant baar imi bhaakh sunaavai | 32 |","meaning_en":"","page":2091}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":2091,"lines":[{"gurmukhi":"ਤੋ ਤੇ ਕਛੁ ਅਛਰ ਰਹਿ ਗਯੋ। ਤੈ ਕਛੁ ਭੰਗ ਕ੍ਰਿਯਾ ਤੇ ਭਯੋ।","roman":"To te kachhu achhar rahi gayo | tai kachhu bhang kriyaa te bhayo |","meaning_en":"","page":2091},{"gurmukhi":"ਤਾ ਤੇ ਤੁਹਿ ਬਰੁ ਰੁਦ੍ਰ ਨ ਦੀਨਾ। ਪੁੰਨ੍ਯ ਦਾਨ ਚਹਿਯਤ ਪੁਨਿ ਕੀਨਾ। ੩੩।","roman":"Taa te tuhi baru rudr na deenaa | punny daan chahiyat puni keenaa | 33 |","meaning_en":"","page":2091}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2091,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਮੰਤ੍ਰ ਸਿਖਾਵਤ ਤਾ ਕੋ। ਲੂਟਾ ਚਾਹਤ ਬਿਪ੍ਰ ਘਰ ਜਾ ਕੋ।","roman":"Ih bidhi mantr sikhaavat taa ko | lootaa chaahat bipr ghar jaa ko |","meaning_en":"","page":2091},{"gurmukhi":"ਜਬ ਵਹੁ ਦਰਬ ਰਹਤ ਹ੍ਵੈ ਜਾਈ। ਔਰ ਧਾਮ ਤਬ ਚਲਤ ਤਕਾਈ। ੩੪।","roman":"Jab vahu darab rahat hvai jaaee | aur dhaam tab chalat takaaee | 34 |","meaning_en":"","page":2091}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2093},{"type":"verse","number":[35],"number_text":"੩੫।","page":2093,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਜੰਤ੍ਰ ਅਰੁ ਤੰਤ੍ਰ ਸਿਧਿ ਜੌ ਇਨਿ ਮਹਿ ਕਛੁ ਹੋਇ।","roman":"Mantr jantr aru tantr sidhi jau ini mahi kachhu hoi |","meaning_en":"","page":2093},{"gurmukhi":"ਹਜਰਤਿ ਹ੍ਵੈ ਆਪਹਿ ਰਹਹਿ ਮਾਗਤ ਫਿਰਤ ਨ ਕੋਇ। ੩੫।","roman":"Hajarti hvai aaphi rahhi maagat phirat na koi | 35 |","meaning_en":"","page":2093}]},{"type":"heading","kind":"chhand","name":"ਦਿਜ ਬਾਜ","gurmukhi":"ਦਿਜ ਬਾਜ","roman":"Dij baaj","meaning_en":"","page":2093},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2093},{"type":"verse","number":[36],"number_text":"੩੬।","page":2093,"lines":[{"gurmukhi":"ਸੁਨਿ ਏ ਬਚਨ ਮਿਸਰ ਰਿਸਿ ਭਰਾ। ਧਿਕ ਧਿਕ ਤਾਕਹਿ ਬਚਨ ਉਚਰਾ।","roman":"Suni e bachan misar risi bharaa | dhik dhik taakhi bachan uchraa |","meaning_en":"","page":2093},{"gurmukhi":"ਤੈ ਹਮਰੀ ਬਾਤ ਕਹ ਜਾਨੈ। ਭਾਂਗ ਖਾਇ ਕੈ ਬੈਨ ਪ੍ਰਮਾਨੈ। ੩੬।","roman":"Tai hamree baat kah jaanai | bhaang khaai kai bain pramaanai | 36 |","meaning_en":"","page":2093}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2093},{"type":"verse","number":[37],"number_text":"੩੭।","page":2093,"lines":[{"gurmukhi":"ਸੁਨੋ ਮਿਸਰ ਤੁਮ ਬਾਤ ਨ ਜਾਨਤ। ਅਹੰਕਾਰ ਕੈ ਬਚਨ ਪ੍ਰਮਾਨਤ।","roman":"Suno misar tum baat na jaanat | ahankaar kai bachan pramaanat |","meaning_en":"","page":2093},{"gurmukhi":"ਭਾਂਗ ਪੀਏ ਬੁਧਿ ਜਾਤ ਨ ਹਰੀ। ਬਿਨੁ ਪੀਏ ਤਵ ਬੁਧਿ ਕਹ ਪਰੀ। ੩੭।","roman":"Bhaang pee'e budhi jaat na haree | binu pee'e tav budhi kah paree | 37 |","meaning_en":"","page":2093}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":2093,"lines":[{"gurmukhi":"ਤੁਮ ਆਪਨ ਸ੍ਯਾਨੇ ਕਹਲਾਵਤ। ਕਬ ਹੀ ਭੂਲਿ ਨ ਭਾਂਗ ਚੜਾਵਤ।","roman":"Tum aapan syaane kahlaavat | kab hee bhooli na bhaang charaavat |","meaning_en":"","page":2093},{"gurmukhi":"ਜਬ ਪੁਨ ਜਾਹੁ ਕਾਜ ਭਿਛਾ ਕੇ। ਕਰਹੋ ਖ੍ਵਾਰ ਰਹਤ ਗ੍ਰਿਹ ਜਾ ਕੇ। ੩੮।","roman":"Jab pun jaahu kaaj bhichhaa ke | karho khvaar rahat grih jaa ke | 38 |","meaning_en":"","page":2093}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":2093,"lines":[{"gurmukhi":"ਜਿਹ ਧਨ ਕੋ ਤੁਮ ਤ੍ਯਾਗ ਦਿਖਾਵਤ। ਦਰ ਦਰ ਤਿਹ ਮਾਂਗਨ ਕਸ ਜਾਵਤ।","roman":"Jih dhan ko tum tyaag dikhaavat | dar dar tih maangan kas jaavat |","meaning_en":"","page":2093},{"gurmukhi":"ਮਹਾ ਮੂੜ ਰਾਜਨ ਕੇ ਪਾਸਨ। ਲੇਤ ਫਿਰਤ ਹੋ ਮਿਸ੍ਰ ਜੂ ਕਨ ਕਨ। ੩੯।","roman":"Mahaa moor raajan ke paasan | let phirat ho misr joo kan kan | 39 |","meaning_en":"","page":2093}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":2093,"lines":[{"gurmukhi":"ਤੁਮ ਜਗ ਮਹਿ ਤ੍ਯਾਗੀ ਕਹਲਾਵਤ। ਸਭ ਲੋਕਨ ਕਹ ਤ੍ਯਾਗ ਦ੍ਰਿੜਾਵਤ।","roman":"Tum jag mahi tyaagee kahlaavat | sabh lokan kah tyaag driraavat |","meaning_en":"","page":2093},{"gurmukhi":"ਜਾ ਕਹ ਮਨ ਬਚ ਕ੍ਰਮ ਤਜਿ ਦੀਜੈ। ਤਾ ਕਹ ਹਾਥ ਉਠਾਇ ਕਸ ਲੀਜੈ। ੪੦।","roman":"Jaa kah man bach kram taji deejai | taa kah haath uthaai kas leejai | 40 |","meaning_en":"","page":2093}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":2093,"lines":[{"gurmukhi":"ਕਾਹੂ ਧਨ ਤ੍ਯਾਗ ਦ੍ਰਿੜਾਵਹਿ। ਕਾਹੂ ਕੋ ਕੋਊ ਗ੍ਰਹਿ ਲਾਵਹਿ।","roman":"Kaahoo dhan tyaag driraavhi | kaahoo ko ko'oo grahi laavhi |","meaning_en":"","page":2093},{"gurmukhi":"ਮਨ ਮਹਿ ਦਰਬ ਠਗਨ ਕੀ ਆਸਾ। ਦ੍ਵਾਰ ਦ੍ਵਾਰ ਡੋਲਤ ਇਹ ਪ੍ਯਾਸਾ। ੪੧।","roman":"Man mahi darab thagan kee aasaa | dvaar dvaar dolat ih pyaasaa | 41 |","meaning_en":"","page":2093}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2093},{"type":"verse","number":[42],"number_text":"੪੨।","page":2093,"lines":[{"gurmukhi":"ਬੇਦ ਬ੍ਯਾਕਰਨ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤ ਇਮ ਉਚਰੈ।","roman":"Bed byaakran saasatr sinmrit im uchrai |","meaning_en":"","page":2093},{"gurmukhi":"ਜਿਨਿ ਕਿਸਹੂ ਤੇ ਏਕ ਟਕਾ ਮੋ ਕੌ ਝਰੈ।","roman":"Jini kishoo te ek takaa mo kau jharai |","meaning_en":"","page":2093},{"gurmukhi":"ਜੇ ਤਿਨ ਕੋ ਕਛੁ ਦੇਤ ਉਸਤਤਿ ਤਾ ਕੀ ਕਰੈ।","roman":"Je tin ko kachhu det usatti taa kee karai |","meaning_en":"","page":2093},{"gurmukhi":"ਹੋ ਜੋ ਧਨ ਦੇਤ ਨ ਤਿਨੈ ਨਿੰਦ ਤਾ ਕੀ ਰਰੈ। ੪੨।","roman":"Ho jo dhan det na tinai nind taa kee rarai | 42 |","meaning_en":"","page":2093}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2093},{"type":"verse","number":[43],"number_text":"੪੩।","page":2093,"lines":[{"gurmukhi":"ਨਿੰਦਿਆ ਅਰੁ ਉਸਤਤਿ ਦੋਊ ਜੀਵਤ ਹੀ ਜਗ ਮਾਹਿ।","roman":"Nindiaa aru usatti do'oo jeevat hee jag maahi |","meaning_en":"","page":2093},{"gurmukhi":"ਜਬ ਮਾਟੀ ਮਾਟੀ ਮਿਲੀ ਨਿੰਦੁਸਤਤਿ ਕਛੁ ਨਾਹਿ। ੪੩।","roman":"Jab maatee maatee milee nindusatti kachhu naahi | 43 |","meaning_en":"","page":2093}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2095},{"type":"verse","number":[44],"number_text":"੪੪।","page":2095,"lines":[{"gurmukhi":"ਦੇਨਹਾਰ ਦਾਇਕਹਿ ਮੁਕਤਿ ਨਹਿ ਕਰਿ ਦਿਯੋ।","roman":"Denhaar daaikhi mukti nahi kari diyo |","meaning_en":"","page":2095},{"gurmukhi":"ਅਨਦਾਇਕ ਤਿਹ ਪੁਤ੍ਰ ਨ ਪਿਤ ਕੋ ਬਧ ਕਿਯੋ।","roman":"Andaaik tih putr na pit ko badh kiyo |","meaning_en":"","page":2095},{"gurmukhi":"ਜਾ ਤੇ ਧਨ ਕਰ ਪਰੈ ਸੁ ਜਸ ਤਾ ਕੋ ਕਰੈ।","roman":"Jaa te dhan kar parai su jas taa ko karai |","meaning_en":"","page":2095},{"gurmukhi":"ਹੋ ਜਾ ਤੇ ਕਛੁ ਨ ਲਹੈ ਨਿੰਦ ਤਿਹ ਉਚਰੈ। ੪੪।","roman":"Ho jaa te kachhu na lahai nind tih uchrai | 44 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2095},{"type":"verse","number":[45],"number_text":"੪੫।","page":2095,"lines":[{"gurmukhi":"ਦੁਹੂੰਅਨ ਸਮ ਜੋਊ ਕਰਿ ਜਾਨੈ। ਨਿੰਦ੍ਯਾ ਉਸਤਤਿ ਸਮ ਕਰਿ ਮਾਨੈ।","roman":"Duhoonan sam jo'oo kari jaanai | nindyaa usatti sam kari maanai |","meaning_en":"","page":2095},{"gurmukhi":"ਹਮ ਤਾਹੀ ਕਹ ਬ੍ਰਹਮ ਪਛਾਨਹਿ। ਵਾਹੀ ਕਹਿ ਦਿਜ ਕੈ ਅਨੁਮਾਨਹਿ। ੪੫।","roman":"Ham taahee kah braham pachhaanhi | vaahee kahi dij kai anumaanhi | 45 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2095},{"type":"verse","number":[46],"number_text":"੪੬।","page":2095,"lines":[{"gurmukhi":"ਏ ਦਿਜ ਜਾ ਤੇ ਜਤਨ ਪਾਇ ਧਨ ਲੇਵਹੀ।","roman":"E dij jaa te jatan paai dhan levhee |","meaning_en":"","page":2095},{"gurmukhi":"ਤਾ ਨਰ ਕਹ ਬਹੁਤ ਭਾਤਿ ਬਡਾਈ ਦੇਵਹੀ।","roman":"Taa nar kah bahut bhaati badaaee devhee |","meaning_en":"","page":2095},{"gurmukhi":"ਮਿਥਯਾ ਉਪਮਾ ਬਕਿ ਕਰਿ ਤਹਿ ਪ੍ਰਸੰਨ ਕਰੈ।","roman":"Mithyaa upmaa baki kari tahi prasann karai |","meaning_en":"","page":2095},{"gurmukhi":"ਹੋ ਘੋਰ ਨਰਕ ਕੇ ਬੀਚ ਅੰਤ ਦੋਊ ਪਰੈ। ੪੬।","roman":"Ho ghor narak ke beech ant do'oo parai | 46 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2095},{"type":"verse","number":[47],"number_text":"੪੭।","page":2095,"lines":[{"gurmukhi":"ਧਨ ਕੇ ਕਾਜ ਕਰਤ ਸਭ ਕਾਜਾ। ਊਚ ਨੀਚ ਰਾਨਾ ਅਰੁ ਰਾਜਾ।","roman":"Dhan ke kaaj karat sabh kaajaa | ooch neech raanaa aru raajaa |","meaning_en":"","page":2095},{"gurmukhi":"ਖ੍ਯਾਲ ਕਾਲ ਕੋ ਕਿਨੂੰ ਨ ਪਾਯੋ। ਜਿਨ ਇਹ ਚੌਦਹ ਲੋਕ ਬਨਾਯੋ। ੪੭।","roman":"Khyaal kaal ko kinoon na paayo | jin ih chaudah lok banaayo | 47 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2095},{"type":"verse","number":[48],"number_text":"੪੮।","page":2095,"lines":[{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਬੇਦ ਬ੍ਯਾਕਰਨ ਪੜਤ ਨਰ।","roman":"Ihee darab ke lobh bed byaakran parat nar |","meaning_en":"","page":2095},{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਮੰਤ੍ਰ ਜੰਤ੍ਰਨ ਉਪਦਿਸ ਕਰ।","roman":"Ihee darab ke lobh mantr jantran updis kar |","meaning_en":"","page":2095},{"gurmukhi":"ਇਹੀ ਦਰਬ ਕੇ ਲੋਭ ਦੇਸ ਪਰਦੇਸ ਸਿਧਾਏ।","roman":"Ihee darab ke lobh des pardes sidhaae |","meaning_en":"","page":2095},{"gurmukhi":"ਹੋ ਪਰੇ ਦੂਰਿ ਕਹ ਜਾਇ ਬਹੁਰਿ ਨਿਜੁ ਦੇਸਨ ਆਏ। ੪੮।","roman":"Ho pare doori kah jaai bahuri niju desan aae | 48 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":2095},{"type":"verse","number":[49],"number_text":"੪੯।","page":2095,"lines":[{"gurmukhi":"ਏਹੀ ਧਨ ਲੋਭ ਤੇ ਪੜਤ ਬ੍ਯਾਕਰਨ ਸਭੈ","roman":"Ehee dhan lobh te parat byaakran sabhai","meaning_en":"","page":2095},{"gurmukhi":"ਏਹੀ ਧਨ ਲੋਭ ਤੇ ਪੁਰਾਨ ਹਾਥ ਧਰੇ ਹੈਂ।","roman":"Ehee dhan lobh te puraan haath dhare hain |","meaning_en":"","page":2095},{"gurmukhi":"ਧਨ ਹੀ ਕੇ ਲੋਭ ਦੇਸ ਛਾਡਿ ਪਰਦੇਸ ਬਸੇ","roman":"Dhan hee ke lobh des chhaadi pardes base","meaning_en":"","page":2095},{"gurmukhi":"ਤਾਤ ਅਰੁ ਮਾਤ ਕੇ ਦਰਸਹੂ ਨ ਕਰੇ ਹੈਂ।","roman":"Taat aru maat ke darashoo na kare hain |","meaning_en":"","page":2095},{"gurmukhi":"ਊਚੇ ਦ੍ਰੁਮ ਸਾਲ ਤਹਾ ਲਾਂਬੇ ਬਟ ਤਾਲ ਜਹਾ।","roman":"Ooche drum saal tahaa laanbe bat taal jahaa |","meaning_en":"","page":2095},{"gurmukhi":"ਤਿਨ ਮੈ ਸਿਧਾਤ ਹੈ ਨ ਜੀ ਮੈ ਨੈਕੁ ਡਰੇ ਹੈਂ।","roman":"Tin mai sidhaat hai na jee mai naiku dare hain |","meaning_en":"","page":2095},{"gurmukhi":"ਧਨ ਕੈ ਨੁਰਾਗੀ ਹੈਂ ਕਹਾਵਤ ਤਿਆਗੀ ਆਪੁ","roman":"Dhan kai nuraagee hain kahaavat tiaagee aapu","meaning_en":"","page":2095},{"gurmukhi":"ਕਾਸੀ ਬੀਚ ਜਏ ਤੇ ਕਮਾਊ ਜਾਇ ਮਰੇ ਹੈਂ। ੪੯।","roman":"Kaasee beech jae te kamaaoo jaai mare hain | 49 |","meaning_en":"","page":2095}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"","page":2097},{"type":"verse","number":[50],"number_text":"੫੦।","page":2097,"lines":[{"gurmukhi":"ਲਾਲਚ ਏਕ ਲਗੈ ਧਨ ਕੇ ਸਿਰ ਮਧਿ ਜਟਾਨ ਕੇ ਜੂਟ ਸਵਾਰੈ।","roman":"Laalach ek lagai dhan ke sir madhi jataan ke joot savaarai |","meaning_en":"","page":2097},{"gurmukhi":"ਕਾਠ ਕੀ ਕੰਠਿਨ ਕੌ ਧਰਿ ਕੈ ਇਕ ਕਾਨਨ ਮੈ ਬਿਨੁ ਕਾਨਿ ਪਧਾਰੈ।","roman":"Kaath kee kanthin kau dhari kai ik kaanan mai binu kaani padhaarai |","meaning_en":"","page":2097},{"gurmukhi":"ਮੋਚਨ ਕੌ ਗਹਿ ਕੈ ਇਕ ਹਾਥਨ ਸੀਸ ਹੂ ਕੇ ਸਭ ਕੇਸ ਉਪਾਰੈ।","roman":"Mochan kau gahi kai ik haathan sees hoo ke sabh kes upaarai |","meaning_en":"","page":2097},{"gurmukhi":"ਡਿੰਭੁ ਕਰੈ ਜਗ ਡੰਡਨ ਕੌ ਇਹ ਲੋਕ ਗਯੋ ਪਰਲੋਕ ਬਿਗਾਰੈ। ੫੦।","roman":"Dinbhu karai jag dandan kau ih lok gayo parlok bigaarai | 50 |","meaning_en":"","page":2097}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":2097,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੇ ਲਿੰਗ ਬਨਾਇ ਕੈ ਪੂਜਤ ਤਾ ਮੈ ਕਹੋ ਇਨ ਕਾ ਸਿਧਿ ਪਾਈ।","roman":"Maatee ke ling banaai kai poojat taa mai kaho in kaa sidhi paaee |","meaning_en":"","page":2097},{"gurmukhi":"ਜੋ ਨਿਰਜੋਤਿ ਭਯੋ ਜਗ ਜਾਨਤ ਤਾਹਿ ਕੇ ਆਗੇ ਲੈ ਜੋਤਿ ਜਗਾਈ।","roman":"Jo nirjoti bhayo jag jaanat taahi ke aage lai joti jagaaee |","meaning_en":"","page":2097},{"gurmukhi":"ਪਾਇ ਪਰੇ ਪਰਮੇਸ੍ਵਰ ਜਾਨਿ ਅਜਾਨ ਬਡੈ ਕਰਿ ਕੈ ਹਠਤਾਈ।","roman":"Paai pare parmesvar jaani ajaan badai kari kai hathtaaee |","meaning_en":"","page":2097},{"gurmukhi":"ਚੇਤ ਅਚੇਤ ਸੁਚੇਤਨ ਕੋ ਚਿਤ ਕੀ ਤਜਿ ਕੈ ਚਟ ਦੈ ਦੁਚਿਤਾਈ। ੫੧।","roman":"Chet achet suchetan ko chit kee taji kai chat dai duchitaaee | 51 |","meaning_en":"","page":2097}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2097,"lines":[{"gurmukhi":"ਕਾਸੀ ਕੇ ਬੀਚ ਪੜੈ ਬਹੁ ਕਾਲ ਬੁਟੰਤ ਮੈ ਅੰਤ ਮਰੈ ਪੁਨਿ ਜਾਈ।","roman":"Kaasee ke beech parai bahu kaal butant mai ant marai puni jaaee |","meaning_en":"","page":2097},{"gurmukhi":"ਤਾਤ ਰਹਾ ਅਰੁ ਮਾਤ ਕਹੂੰ ਬਨਿਤਾ ਸੁਤ ਪੁਤ੍ਰ ਕਲਤ੍ਰਨ ਭਾਈ।","roman":"Taat rahaa aru maat kahoon banitaa sut putr kaltran bhaaee |","meaning_en":"","page":2097},{"gurmukhi":"ਦੇਸ ਬਿਦੇਸ ਫਿਰੈ ਤਜਿ ਕੈ ਘਰ ਥੋਰੀ ਸੀ ਸੀਖਿ ਕੈ ਚਾਤੁਰਤਾਈ।","roman":"Des bides phirai taji kai ghar thoree see seekhi kai chaaturtaaee |","meaning_en":"","page":2097},{"gurmukhi":"ਲੋਭ ਕੀ ਲੀਕ ਨ ਲਾਂਘੀ ਕਿਸੂ ਨਰ ਲੋਭ ਰਹਾ ਸਭ ਲੋਗ ਲੁਭਾਈ। ੫੨।","roman":"Lobh kee leek na laanghee kisoo nar lobh rahaa sabh log lubhaaee | 52 |","meaning_en":"","page":2097}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":2097},{"type":"verse","number":[53],"number_text":"੫੩।","page":2097,"lines":[{"gurmukhi":"ਏਕਨ ਕੋ ਮੂੰਡਿ ਮਾਂਡਿ ਏਕਨ ਸੌ ਲੇਹਿ ਡਾਂਡ","roman":"Ekan ko moondi maandi ekan sau lehi daand","meaning_en":"","page":2097},{"gurmukhi":"ਏਕਨ ਕੈ ਕੰਠੀ ਕਾਠ ਕੰਠ ਮੈ ਡਰਤ ਹੈਂ।","roman":"Ekan kai kanthee kaath kanth mai darat hain |","meaning_en":"","page":2097},{"gurmukhi":"ਏਕਨ ਦ੍ਰਿੜਾਵੈ ਮੰਤ੍ਰ ਏਕਨ ਲਿਖਾਵੈ ਜੰਤ੍ਰ","roman":"Ekan driraavai mantr ekan likhaavai jantr","meaning_en":"","page":2097},{"gurmukhi":"ਏਕਨ ਕੌ ਤੰਤ੍ਰਨ ਪ੍ਰਬੋਧ੍ਯੋ ਈ ਕਰਤ ਹੈਂ।","roman":"Ekan kau tantran prabodhyo ee karat hain |","meaning_en":"","page":2097},{"gurmukhi":"ਏਕਨ ਕੇ ਬਿਦ੍ਯਾ ਕੋ ਬਿਵਾਦਨ ਬਤਾਵੈ ਡਿੰਭ","roman":"Ekan ke bidyaa ko bivaadan bataavai dinbh","meaning_en":"","page":2097},{"gurmukhi":"ਜਗ ਕੋ ਦਿਖਾਇ ਜ੍ਯੋ ਕ੍ਯੋ ਮਾਤ੍ਰਾ ਕੌ ਹਰਤ ਹੈ।","roman":"Jag ko dikhaai jyo kyo maatraa kau harat hai |","meaning_en":"","page":2097},{"gurmukhi":"ਮੈਯਾ ਕੌ ਨ ਮਾਨੈ ਮਹਾ ਕਾਲੈ ਨ ਮਨਾਵੈ","roman":"Maiyaa kau na maanai mahaa kaalai na manaavai","meaning_en":"","page":2097},{"gurmukhi":"ਮੂੜ ਮਾਟੀ ਕੌ ਮਾਨਤ ਤਾ ਤੇ ਮਾਂਗਤ ਮਰਤ ਹੈ। ੫੩।","roman":"Moor maatee kau maanat taa te maangat marat hai | 53 |","meaning_en":"","page":2097}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":2097},{"type":"verse","number":[54],"number_text":"੫੪।","page":2097,"lines":[{"gurmukhi":"ਚੇਤ ਅਚੇਤੁ ਕੀਏ ਜਿਨ ਚੇਤਨ ਤਾਹਿ ਅਚੇਤ ਨ ਕੋ ਠਹਰਾਵੈ।","roman":"Chet achetu kee'e jin chetan taahi achet na ko thahraavai |","meaning_en":"","page":2097},{"gurmukhi":"ਤਾਹਿ ਕਹੈ ਪਰਮੇਸ੍ਵਰ ਕੈ ਮਨ ਮਾਹਿ ਕਹੇ ਘਟਿ ਮੋਲ ਬਿਕਾਵੈ।","roman":"Taahi kahai parmesvar kai man maahi kahe ghati mol bikaavai |","meaning_en":"","page":2097},{"gurmukhi":"ਜਾਨਤ ਹੈ ਨ ਅਜਾਨ ਬਡੈ ਸੁ ਇਤੇ ਪਰ ਪੰਡਿਤ ਆਪੁ ਕਹਾਵੈ।","roman":"Jaanat hai na ajaan badai su ite par pandit aapu kahaavai |","meaning_en":"","page":2097},{"gurmukhi":"ਲਾਜ ਕੇ ਮਾਰੇ ਮਰੈ ਨ ਮਹਾ ਲਟ ਐਠਹਿ ਐਠ ਅਮੈਠਿ ਗਵਾਵੈ। ੫੪।","roman":"Laaj ke maare marai na mahaa lat aithhi aith amaithi gavaavai | 54 |","meaning_en":"","page":2097}]},{"type":"heading","kind":"chhand","name":"ਬਿਜੈ ਛੰਦ","gurmukhi":"ਬਿਜੈ ਛੰਦ","roman":"Bijai chhand","meaning_en":"","page":2097},{"type":"verse","number":[55],"number_text":"੫੫।","page":2097,"lines":[{"gurmukhi":"ਗਤਮਾਨ ਕਹਾਵਤ ਗਾਤ ਸਭੈ ਕਛੂ ਜਾਨੈ ਨ ਬਾਤ ਗਤਾਗਤ ਹੈ।","roman":"Gatmaan kahaavat gaat sabhai kachhoo jaanai na baat gataagat hai |","meaning_en":"","page":2097},{"gurmukhi":"ਦੁਤਿਮਾਨ ਘਨੇ ਬਲਵਾਨ ਬਡੇ ਹਮ ਜਾਨਤ ਜੋਗ ਮਧੇ ਜਤ ਹੈ।","roman":"Dutimaan ghane balvaan bade ham jaanat jog madhe jat hai |","meaning_en":"","page":2097},{"gurmukhi":"ਪਾਹਨ ਕੈ ਕਹੈ ਬੀਚ ਸਹੀ ਸਿਵ ਜਾਨੈ ਨ ਮੂੜ ਮਹਾ ਮਤ ਹੈ।","roman":"Paahan kai kahai beech sahee siv jaanai na moor mahaa mat hai |","meaning_en":"","page":2097},{"gurmukhi":"ਤੁਮਹੂੰ ਨ ਬਿਚਾਰਿ ਸੁ ਜਾਨ ਕਹੋ ਇਨ ਮੈ ਕਹਾ ਪਾਰਬਤੀ ਪਤਿ ਹੈ। ੫੫।","roman":"Tumhoon na bichaari su jaan kaho in mai kahaa paarabtee pati hai | 55 |","meaning_en":"","page":2097}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2099,"lines":[{"gurmukhi":"ਮਾਟੀ ਕੌ ਸੀਸ ਨਿਵਾਵਤ ਹੈ ਜੜ ਯਾ ਤੇ ਕਹੋ ਤੁਹਿ ਕਾ ਸਿਧਿ ਐਹੈ।","roman":"Maatee kau sees nivaavat hai jar yaa te kaho tuhi kaa sidhi aihai |","meaning_en":"","page":2099},{"gurmukhi":"ਜੌਨ ਰਿਝਾਇ ਲਯੋ ਜਗ ਕੌ ਤਵ ਚਾਵਰ ਡਾਰਤ ਰੀਝਿ ਨ ਜੈ ਹੈ।","roman":"Jaun rijhaai layo jag kau tav chaavar daarat reejhi na jai hai |","meaning_en":"","page":2099},{"gurmukhi":"ਧੂਪ ਜਗਾਇ ਕੈ ਸੰਖ ਬਜਾਇ ਸੁ ਫੂਲਨ ਕੀ ਬਰਖਾ ਬਰਖੈ ਹੈ।","roman":"Dhoop jagaai kai sankh bajaai su phoolan kee barkhaa barkhai hai |","meaning_en":"","page":2099},{"gurmukhi":"ਅੰਤ ਉਪਾਇ ਕੈ ਹਾਰਿ ਹੈਂ ਰੇ ਪਸੁ ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਰ ਨ ਪੈ ਹੈ। ੫੬।","roman":"Ant upaai kai haari hain re pasu paahan mai parmesr na pai hai | 56 |","meaning_en":"","page":2099}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2099,"lines":[{"gurmukhi":"ਏਕਨ ਜੰਤ੍ਰ ਸਿਖਾਵਤ ਹੈ ਦਿਜ ਏਕਨ ਮੰਤ੍ਰ ਪ੍ਰਯੋਗ ਬਤਾਵੈ।","roman":"Ekan jantr sikhaavat hai dij ekan mantr prayog bataavai |","meaning_en":"","page":2099},{"gurmukhi":"ਜੋ ਨ ਭਿਜੈ ਇਨ ਬਾਤਨ ਤੇ ਤਿਹ ਗੀਤਿ ਕਬਿਤ ਸਲੋਕ ਸੁਨਾਵੈ।","roman":"Jo na bhijai in baatan te tih geeti kabit salok sunaavai |","meaning_en":"","page":2099},{"gurmukhi":"ਦ੍ਯੋਸ ਹਿਰੈ ਧਨ ਲੋਗਨ ਕੇ ਗ੍ਰਿਹ ਚੋਰੁ ਚਕੈ ਠਗ ਦੇਖਿ ਲਜਾਵੈ।","roman":"Dyos hirai dhan logan ke grih choru chakai thag dekhi lajaavai |","meaning_en":"","page":2099},{"gurmukhi":"ਕਾਨਿ ਕਰੈ ਨਹਿ ਕਾਜੀ ਕੁਟਵਾਰ ਕੀ ਮੂੰਡਿ ਕੈ ਮੂੰਡਿ ਮੁਰੀਦਨ ਖਾਵੈ। ੫੭।","roman":"Kaani karai nahi kaajee kutvaar kee moondi kai moondi mureedan khaavai | 57 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2099},{"type":"verse","number":[58],"number_text":"੫੮।","page":2099,"lines":[{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰੇ ਜੋ ਹੈ ਅਧਿਕ ਅਚੇਤ।","roman":"Paahan kee poojaa kare jo hai adhik achet |","meaning_en":"","page":2099},{"gurmukhi":"ਭਾਂਗ ਨ ਏਤੇ ਪਰ ਭਖੈ ਜਾਨਤ ਆਪ ਸੁਚੇਤ। ੫੮।","roman":"Bhaang na ete par bhakhai jaanat aap suchet | 58 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"","page":2099},{"type":"verse","number":[59],"number_text":"੫੯।","page":2099,"lines":[{"gurmukhi":"ਧਨ ਕੇ ਲਗਿ ਲੋਭ ਗਏ ਅਨਤੈ। ਤਜਿ ਮਾਤ ਪਿਤਾ ਸੁਤ ਬਾਲ ਕਿਤੈ।","roman":"Dhan ke lagi lobh gae antai | taji maat pitaa sut baal kitai |","meaning_en":"","page":2099},{"gurmukhi":"ਬਸਿ ਕੈ ਬਹੁ ਮਾਸ ਤਹਾ ਹੀ ਮਰੈ। ਫਿਰਿ ਕੈ ਗ੍ਰਿਹਿ ਕੇ ਨਹਿ ਪੰਥ ਪਰੈ। ੫੯।","roman":"Basi kai bahu maas tahaa hee marai | phiri kai grihi ke nahi panth parai | 59 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2099},{"type":"verse","number":[60],"number_text":"੬੦।","page":2099,"lines":[{"gurmukhi":"ਧਨੀ ਲੋਗ ਹੈ ਪੁਹਪ ਸਮ ਗੁਨਿ ਜਨ ਭੌਰ ਬਿਚਾਰ।","roman":"Dhanee log hai puhap sam guni jan bhaur bichaar |","meaning_en":"","page":2099},{"gurmukhi":"ਗੂੰਜ ਰਹਤ ਤਿਹ ਪਰ ਸਦਾ ਸਭ ਧਨ ਧਾਮ ਬਿਸਾਰ। ੬੦।","roman":"Goonj rahat tih par sadaa sabh dhan dhaam bisaar | 60 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2099},{"type":"verse","number":[61],"number_text":"੬੧।","page":2099,"lines":[{"gurmukhi":"ਸਭ ਕੋਊ ਅੰਤ ਕਾਲ ਬਸਿ ਭਯਾ। ਧਨ ਕੀ ਆਸ ਨਿਕਰਿ ਤਜਿ ਗਯਾ।","roman":"Sabh ko'oo ant kaal basi bhayaa | dhan kee aas nikri taji gayaa |","meaning_en":"","page":2099},{"gurmukhi":"ਆਸਾ ਕਰਤ ਗਯਾ ਸੰਸਾਰਾ। ਇਹ ਆਸਾ ਕੋ ਵਾਰ ਨ ਪਾਰਾ। ੬੧।","roman":"Aasaa karat gayaa sansaaraa | ih aasaa ko vaar na paaraa | 61 |","meaning_en":"","page":2099}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2099,"lines":[{"gurmukhi":"ਏਕ ਨਿਰਾਸ ਵਹੈ ਕਰਤਾਰਾ। ਜਿਨ ਕੀਨਾ ਇਹ ਸਕਲ ਪਸਾਰਾ।","roman":"Ek niraas vahai kartaaraa | jin keenaa ih sakal pasaaraa |","meaning_en":"","page":2099},{"gurmukhi":"ਆਸਾ ਰਹਿਤ ਔਰ ਕੋਊ ਨਾਹੀ। ਜਾਨੁ ਲੇਹੁ ਦਿਜਬਰ ਮਨ ਮਾਹੀ। ੬੨।","roman":"Aasaa rahit aur ko'oo naahee | jaanu lehu dijbar man maahee | 62 |","meaning_en":"","page":2099}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2099,"lines":[{"gurmukhi":"ਲੋਭ ਲਗੇ ਧਨ ਕੇ ਏ ਦਿਜਬਰ। ਮਾਂਗਤ ਫਿਰਤ ਸਭਨ ਕੇ ਘਰ ਘਰ।","roman":"Lobh lage dhan ke e dijbar | maangat phirat sabhan ke ghar ghar |","meaning_en":"","page":2099},{"gurmukhi":"ਯਾ ਜਗ ਮਹਿ ਕਰ ਡਿੰਭ ਦਿਖਾਵਤ। ਤੇ ਠਗਿ ਠਗਿ ਸਭ ਕਹ ਧਨ ਖਾਵਤ। ੬੩।","roman":"Yaa jag mahi kar dinbh dikhaavat | te thagi thagi sabh kah dhan khaavat | 63 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2099},{"type":"verse","number":[64],"number_text":"੬੪।","page":2099,"lines":[{"gurmukhi":"ਆਸਾ ਕੀ ਆਸਾ ਲਗੇ ਸਭ ਹੀ ਗਯਾ ਜਹਾਨ।","roman":"Aasaa kee aasaa lage sabh hee gayaa jahaan |","meaning_en":"","page":2099},{"gurmukhi":"ਆਸਾ ਜਗ ਜੀਵਤ ਬਚੀ ਲੀਜੈ ਸਮਝਿ ਸੁਜਾਨ। ੬੪।","roman":"Aasaa jag jeevat bachee leejai samjhi sujaan | 64 |","meaning_en":"","page":2099}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2101},{"type":"verse","number":[65],"number_text":"੬੫।","page":2101,"lines":[{"gurmukhi":"ਆਸਾ ਕਰਤ ਸਗਲ ਜਗ ਜਯਾ। ਆਸਹਿ ਉਪਜ੍ਯਾ ਆਸਹਿ ਭਯਾ।","roman":"Aasaa karat sagal jag jayaa | aashi upjyaa aashi bhayaa |","meaning_en":"","page":2101},{"gurmukhi":"ਆਸਾ ਕਰਤ ਤਰੁਨ ਬ੍ਰਿਧ ਹੂਆ। ਆਸਾ ਕਰਤ ਲੋਗ ਸਭ ਮੂਆ। ੬੫।","roman":"Aasaa karat tarun bridh hooaa | aasaa karat log sabh mooaa | 65 |","meaning_en":"","page":2101}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2101,"lines":[{"gurmukhi":"ਆਸਾ ਕਰਤ ਲੋਗ ਸਭ ਭਏ। ਬਾਲਕ ਹੁਤੋ ਬ੍ਰਿਧ ਹ੍ਵੈ ਗਏ।","roman":"Aasaa karat log sabh bhae | baalak huto bridh hvai gae |","meaning_en":"","page":2101},{"gurmukhi":"ਜਿਤਿ ਕਿਤ ਧਨ ਆਸਾ ਕਰਿ ਡੋਲਹਿ। ਦੇਸ ਬਿਦੇਸ ਧਨਾਸ ਕਲੋਲਹਿ। ੬੬।","roman":"Jiti kit dhan aasaa kari dolhi | des bides dhanaas kalolhi | 66 |","meaning_en":"","page":2101}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2101,"lines":[{"gurmukhi":"ਪਾਹਨ ਕਹੁ ਧਨਾਸ ਸਿਰ ਨ੍ਯਾਵੈ। ਚੇਤ ਅਚੇਤਨ ਕੌ ਠਹਰਾਵੈ।","roman":"Paahan kahu dhanaas sir nyaavai | chet achetan kau thahraavai |","meaning_en":"","page":2101},{"gurmukhi":"ਕਰਤ ਪ੍ਰਪੰਚ ਪੇਟ ਕੇ ਕਾਜਾ। ਊਚ ਨੀਚ ਰਾਨਾ ਅਰੁ ਰਾਜਾ। ੬੭।","roman":"Karat prapanch pet ke kaajaa | ooch neech raanaa aru raajaa | 67 |","meaning_en":"","page":2101}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":2101,"lines":[{"gurmukhi":"ਕਾਹੂ ਕੋ ਸਿਛਾ ਸੁ ਦ੍ਰਿੜਾਵੈ। ਕਾਹੂੰ ਕੌ ਲੈ ਮੂੰਡ ਮੁੰਡਾਵੈ।","roman":"Kaahoo ko sichhaa su driraavai | kaahoon kau lai moond mundaavai |","meaning_en":"","page":2101},{"gurmukhi":"ਕਾਹੂੰ ਪਠੈ ਤੀਰਥਨ ਦੇਹੀ। ਗ੍ਰਿਹ ਕੋ ਦਰਬੁ ਮਾਂਗ ਸਭ ਲੇਹੀ। ੬੮।","roman":"Kaahoon pathai teerthan dehee | grih ko darbu maang sabh lehee | 68 |","meaning_en":"","page":2101}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2101,"lines":[{"gurmukhi":"ਜਿਹ ਨਰ ਕੋ ਧਨਵਾਨ ਤਕਾਵੈ। ਜੋਨਿ ਸਿਲਾ ਮਹਿ ਤਾਹਿ ਫਸਾਵੈ।","roman":"Jih nar ko dhanvaan takaavai | joni silaa mahi taahi phasaavai |","meaning_en":"","page":2101},{"gurmukhi":"ਬਹੁਰਿ ਡੰਡ ਤਿਹ ਮੂੰਡਿ ਚੁਕਾਹੀ। ਕਾਢਿ ਦੇਤ ਤਾ ਕੇ ਪੁਨਿ ਮਾਹੀ। ੬੯।","roman":"Bahuri dand tih moondi chukaahee | kaadhi det taa ke puni maahee | 69 |","meaning_en":"","page":2101}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2101,"lines":[{"gurmukhi":"ਇਨ ਲੋਗਨ ਧਨ ਹੀ ਕੀ ਆਸਾ। ਸ੍ਰੀ ਹਰਿ ਜੀ ਕੀ ਨਾਹਿ ਪ੍ਯਾਸਾ।","roman":"In logan dhan hee kee aasaa | sree hari jee kee naahi pyaasaa |","meaning_en":"","page":2101},{"gurmukhi":"ਡਿੰਭਿ ਜਗਤ ਕਹ ਕਰਿ ਪਰਚਾਵੈ। ਲਛਿਮੀ ਹਰ ਜ੍ਯੋ ਤ੍ਯੋ ਲੈ ਆਵੈ। ੭੦।","roman":"Dinbhi jagat kah kari parchaavai | lachhimee har jyo tyo lai aavai | 70 |","meaning_en":"","page":2101}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2101},{"type":"verse","number":[71],"number_text":"੭੧।","page":2101,"lines":[{"gurmukhi":"ਸੁਨੁ ਪੁਤ੍ਰੀ ਤੈ ਬਾਤ ਨ ਜਾਨੈ। ਸਿਵ ਕਹ ਕਰਿ ਪਾਹਨ ਪਹਿਚਾਨੈ।","roman":"Sunu putree tai baat na jaanai | siv kah kari paahan pahichaanai |","meaning_en":"","page":2101},{"gurmukhi":"ਬਿਪ੍ਰਨ ਕੌ ਸਭ ਹੀ ਸਿਰ ਨ੍ਯਾਵੈ। ਚਰਨੋਦਕ ਲੈ ਮਾਥ ਚੜਾਵੈ। ੭੧।","roman":"Bipran kau sabh hee sir nyaavai | charnodak lai maath charaavai | 71 |","meaning_en":"","page":2101}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":2101,"lines":[{"gurmukhi":"ਪੂਜਾ ਕਰਤ ਸਗਲ ਜਗ ਇਨ ਕੀ। ਨਿੰਦ੍ਯਾ ਕਰਤ ਮੂੜ ਤੈ ਜਿਨ ਕੀ।","roman":"Poojaa karat sagal jag in kee | nindyaa karat moor tai jin kee |","meaning_en":"","page":2101},{"gurmukhi":"ਏ ਹੈ ਪਰਮ ਪੁਰਾਤਨ ਦਿਜਬਰ। ਸਦਾ ਸਰਾਹਤ ਜਿਨ ਕਹ ਨ੍ਰਿਪ ਬਰ। ੭੨।","roman":"E hai param puraatan dijbar | sadaa saraahat jin kah nrip bar | 72 |","meaning_en":"","page":2101}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2101},{"type":"verse","number":[73],"number_text":"੭੩।","page":2101,"lines":[{"gurmukhi":"ਸੁਨ ਮੂਰਖ ਦਿਜ ਤੈ ਨਹਿ ਜਾਨੀ। ਪਰਮ ਜੋਤਿ ਪਾਹਨ ਪਹਿਚਾਨੀ।","roman":"Sun moorakh dij tai nahi jaanee | param joti paahan pahichaanee |","meaning_en":"","page":2101},{"gurmukhi":"ਇਨ ਮਹਿ ਪਰਮ ਪੁਰਖ ਤੈ ਜਾਨਾ। ਤਜਿ ਸ੍ਯਾਨਪ ਹ੍ਵੈ ਗਯੋ ਅਯਾਨਾ। ੭੩।","roman":"In mahi param purakh tai jaanaa | taji syaanap hvai gayo ayaanaa | 73 |","meaning_en":"","page":2101}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2101},{"type":"verse","number":[74],"number_text":"੭੪।","page":2101,"lines":[{"gurmukhi":"ਲੈਨੌ ਹੋਇ ਸੁ ਲੈ ਦਿਜ ਮੁਹਿ ਨ ਝੁਠਾਇਯੈ।","roman":"Lainau hoi su lai dij muhi na jhuthaaiyai |","meaning_en":"","page":2101},{"gurmukhi":"ਪਾਹਨ ਮੈ ਪਰਮੇਸ੍ਵਰ ਨ ਭਾਖਿ ਸੁਨਾਇਯੈ।","roman":"Paahan mai parmesvar na bhaakhi sunaaiyai |","meaning_en":"","page":2101},{"gurmukhi":"ਇਨ ਲੋਗਨ ਪਾਹਨ ਮਹਿ ਸਿਵ ਠਹਰਾਇ ਕੈ।","roman":"In logan paahan mahi siv thahraai kai |","meaning_en":"","page":2101},{"gurmukhi":"ਹੋ ਮੂੜਨ ਲੀਜਹੁ ਲੂਟ ਹਰਖ ਉਪਜਾਇ ਕੈ। ੭੪।","roman":"Ho mooran leejhu loot harakh upjaai kai | 74 |","meaning_en":"","page":2101}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2103,"lines":[{"gurmukhi":"ਕਾਹੂ ਕਹ ਪਾਹਨ ਮਹਿ ਬ੍ਰਹਮ ਬਤਾਤ ਹੈ।","roman":"Kaahoo kah paahan mahi braham bataat hai |","meaning_en":"","page":2103},{"gurmukhi":"ਜਲ ਡੂਬਨ ਹਿਤ ਕਿਸਹੂੰ ਤੀਰਥ ਪਠਾਤ ਹੈ।","roman":"Jal dooban hit kishoon teerath pathaat hai |","meaning_en":"","page":2103},{"gurmukhi":"ਜ੍ਯੋ ਤ੍ਯੋ ਧਨ ਹਰ ਲੇਤ ਜਤਨ ਅਨਗਨਿਤ ਕਰ।","roman":"Jyo tyo dhan har let jatan anagnit kar |","meaning_en":"","page":2103},{"gurmukhi":"ਹੋ ਟਕਾ ਗਾਠਿ ਮਹਿ ਲਏ ਨ ਦੇਹੀ ਜਾਨ ਘਰ। ੭੫।","roman":"Ho takaa gaathi mahi lae na dehee jaan ghar | 75 |","meaning_en":"","page":2103}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":2103,"lines":[{"gurmukhi":"ਧਨੀ ਪੁਰਖ ਕਹ ਲਖਿ ਦਿਜ ਦੋਖ ਲਗਾਵਹੀ।","roman":"Dhanee purakh kah lakhi dij dokh lagaavhee |","meaning_en":"","page":2103},{"gurmukhi":"ਹੋਮ ਜਗ੍ਯ ਤਾ ਤੇ ਬਹੁ ਭਾਤ ਕਰਾਵਹੀ।","roman":"Hom jagy taa te bahu bhaat karaavhee |","meaning_en":"","page":2103},{"gurmukhi":"ਧਨਿਯਹਿ ਕਰਿ ਨਿਰਧਨੀ ਜਾਤ ਧਨ ਖਾਇ ਕੈ।","roman":"Dhaniyhi kari niradhnee jaat dhan khaai kai |","meaning_en":"","page":2103},{"gurmukhi":"ਹੋ ਬਹੁਰਿ ਨ ਤਾ ਕੌ ਬਦਨ ਦਿਖਾਵਤ ਆਇ ਕੈ। ੭੬।","roman":"Ho bahuri na taa kau badan dikhaavat aai kai | 76 |","meaning_en":"","page":2103}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2103},{"type":"verse","number":[77],"number_text":"੭੭।","page":2103,"lines":[{"gurmukhi":"ਕਾਹੂ ਲੌ ਤੀਰਥਨ ਸਿਧਾਵੈ। ਕਾਹੂ ਅਫਲ ਪ੍ਰਯੋਗ ਬਤਾਵੈ।","roman":"Kaahoo lau teerthan sidhaavai | kaahoo aphal prayog bataavai |","meaning_en":"","page":2103},{"gurmukhi":"ਕਾਕਨ ਜ੍ਯੋ ਮੰਡਰਾਤ ਧਨੂਪਰ। ਜ੍ਯੋ ਕਿਲਕਾ ਮਛਰੀਯੈ ਦੂਪਰ। ੭੭।","roman":"Kaakan jyo mandraat dhanoopar | jyo kilkaa machhreeyai doopar | 77 |","meaning_en":"","page":2103}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2103,"lines":[{"gurmukhi":"ਜ੍ਯੋ ਦ੍ਵੈ ਸ੍ਵਾਨ ਏਕ ਹਡਿਯਾ ਪਰ। ਭੂਸਤ ਮਨੋ ਬਾਦਿ ਬਿਦ੍ਯਾਧਰ।","roman":"Jyo dvai svaan ek hadiyaa par | bhoosat mano baadi bidyaadhar |","meaning_en":"","page":2103},{"gurmukhi":"ਬਾਹਰ ਕਰਤ ਬੇਦ ਕੀ ਚਰਚਾ। ਤਨ ਅਰੁ ਮਨ ਧਨ ਹੀ ਕੀ ਅਰਚਾ। ੭੮।","roman":"Baahar karat bed kee charchaa | tan aru man dhan hee kee archaa | 78 |","meaning_en":"","page":2103}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2103},{"type":"verse","number":[79],"number_text":"੭੯।","page":2103,"lines":[{"gurmukhi":"ਧਨ ਕੀ ਆਸਾ ਮਨ ਰਹੇ ਬਾਹਰ ਪੂਜਤ ਦੇਵ।","roman":"Dhan kee aasaa man rahe baahar poojat dev |","meaning_en":"","page":2103},{"gurmukhi":"ਨ ਹਰਿ ਮਿਲਾ ਨ ਧਨ ਭਯੋ ਬ੍ਰਿਥਾ ਭਈ ਸਭ ਸੇਵ। ੭੯।","roman":"Na hari milaa na dhan bhayo brithaa bhaee sabh sev | 79 |","meaning_en":"","page":2103}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2103},{"type":"verse","number":[80],"number_text":"੮੦।","page":2103,"lines":[{"gurmukhi":"ਏ ਬਿਦ੍ਯਾ ਬਲ ਕਰਿਹ ਜੋਗ ਕੀ ਬਾਤ ਨ ਜਾਨੈ।","roman":"E bidyaa bal karih jog kee baat na jaanai |","meaning_en":"","page":2103},{"gurmukhi":"ਏ ਸੁਚੇਤ ਕਰਿ ਰਹਹਿ ਹਮਨਿ ਆਚੇਤ ਪ੍ਰਮਾਨੈ।","roman":"E suchet kari rahhi hamni aachet pramaanai |","meaning_en":"","page":2103},{"gurmukhi":"ਕਹਾ ਭਯੌ ਜੌ ਭਾਂਗ ਭੂਲਿ ਭੌਦੂ ਨਹਿ ਖਾਈ।","roman":"Kahaa bhayau jau bhaang bhooli bhaudoo nahi khaaee |","meaning_en":"","page":2103},{"gurmukhi":"ਹੋ ਨਿਜੁ ਤਨ ਤੇ ਬਿਸੰਭਾਰ ਰਹਤ ਸਭ ਲਖਤ ਲੁਕਾਈ। ੮੦।","roman":"Ho niju tan te bisanbhaar rahat sabh lakhat lukaaee | 80 |","meaning_en":"","page":2103}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2103,"lines":[{"gurmukhi":"ਭਾਂਗ ਖਾਇ ਭਟ ਭਿੜਹਿ ਗਜਨ ਕੇ ਦਾਂਤ ਉਪਾਰਹਿ।","roman":"Bhaang khaai bhat bhirhi gajan ke daant upaarhi |","meaning_en":"","page":2103},{"gurmukhi":"ਸਿਮਟਿ ਸਾਂਗ ਸੰਗ੍ਰਹਹਿ ਸਾਰ ਸਨਮੁਖ ਹ੍ਵੈ ਝਾਰਹਿ।","roman":"Simti saang sangrahhi saar sanmukh hvai jhaarhi |","meaning_en":"","page":2103},{"gurmukhi":"ਤੈ ਮੂਜੀ ਪੀ ਭਾਂਗ ਕਹੋ ਕਾ ਕਾਜ ਸਵਰਿ ਹੈ।","roman":"Tai moojee pee bhaang kaho kaa kaaj savri hai |","meaning_en":"","page":2103},{"gurmukhi":"ਹੋ ਹ੍ਵੈ ਕੈ ਮ੍ਰਿਤਕ ਸਮਾਨ ਜਾਇ ਔਧੇ ਮੁਖ ਪਰਿ ਹੈ। ੮੧।","roman":"Ho hvai kai mritak samaan jaai audhe mukh pari hai | 81 |","meaning_en":"","page":2103}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"","page":2103},{"type":"verse","number":[82],"number_text":"੮੨।","page":2103,"lines":[{"gurmukhi":"ਸੁਨੋ ਮਿਸ੍ਰ ਸਿਛਾ ਇਨੀ ਕੋ ਸੁ ਦੀਜੈ। ਮਹਾ ਝੂਠ ਤੇ ਰਾਖਿ ਕੈ ਮੋਹਿ ਲੀਜੈ।","roman":"Suno misr sichhaa inee ko su deejai | mahaa jhooth te raakhi kai mohi leejai |","meaning_en":"","page":2103},{"gurmukhi":"ਇਤੋ ਝੂਠ ਕੈ ਔਰ ਨੀਕੋ ਦ੍ਰਿੜਾਵੌ। ਕਹਾ ਚਾਮ ਕੇ ਦਾਮ ਕੈ ਕੈ ਚਲਾਵੌ। ੮੨।","roman":"Ito jhooth kai aur neeko driraavau | kahaa chaam ke daam kai kai chalaavau | 82 |","meaning_en":"","page":2103}]},{"type":"verse","number":[83],"number_text":"੮੩।","page":2103,"lines":[{"gurmukhi":"ਮਹਾ ਘੋਰ ਈ ਨਰਕ ਕੇ ਬੀਚ ਜੈ ਹੌ। ਕਿ ਚੰਡਾਲ ਕੀ ਜੋਨਿ ਮੈ ਔਤਰੈ ਹੌ।","roman":"Mahaa ghor ee narak ke beech jai hau | ki chandaal kee joni mai autrai hau |","meaning_en":"","page":2103},{"gurmukhi":"ਕਿ ਟਾਂਗੇ ਮਰੋਗੇ ਬਧੇ ਮ੍ਰਿਤਸ਼ਾਲਾ। ਸਨੈ ਬੰਧੁ ਪੁਤ੍ਰਾ ਕਲਤ੍ਰਾਨ ਬਾਲਾ। ੮੩।","roman":"Ki taange maroge badhe mritshaalaa | sanai bandhu putraa kaltraan baalaa | 83 |","meaning_en":"","page":2103}]},{"type":"verse","number":[84],"number_text":"੮੪।","page":2105,"lines":[{"gurmukhi":"ਕਹੋ ਮਿਸ੍ਰ ਆਗੇ ਕਹਾ ਜ੍ਵਾਬ ਦੈਹੋ। ਜਬੈ ਕਾਲ ਕੇ ਜਾਲ ਮੈ ਫਾਸਿ ਜੈ ਹੋ।","roman":"Kaho misr aage kahaa jvaab daiho | jabai kaal ke jaal mai phaasi jai ho |","meaning_en":"","page":2105},{"gurmukhi":"ਕਹੋ ਕੌਨ ਸੋ ਪਾਠ ਕੈਹੋ ਤਹਾ ਹੀ। ਤਊ ਲਿੰਗ ਪੂਜਾ ਕਰੌਗੇ ਉਹਾ ਹੀ। ੮੪।","roman":"Kaho kaun so paath kaiho tahaa hee | taoo ling poojaa karauge uhaa hee | 84 |","meaning_en":"","page":2105}]},{"type":"verse","number":[85],"number_text":"੮੫।","page":2105,"lines":[{"gurmukhi":"ਤਹਾ ਰੁਦ੍ਰ ਐ ਹੈ ਕਿ ਸ੍ਰੀ ਕ੍ਰਿਸਨ ਐ ਹੈ। ਜਹਾ ਬਾਧਿ ਸ੍ਰੀ ਕਾਲ ਤੋ ਕੌ ਚਲੇ ਹੈ।","roman":"Tahaa rudr ai hai ki sree krisan ai hai | jahaa baadhi sree kaal to kau chale hai |","meaning_en":"","page":2105},{"gurmukhi":"ਕਿਧੌ ਆਨਿ ਕੈ ਰਾਮ ਹ੍ਵੈ ਹੈ ਸਹਾਈ। ਜਹਾ ਪੁਤ੍ਰ ਮਾਤਾ ਨ ਤਾਤਾ ਨ ਭਾਈ। ੮੫।","roman":"Kidhau aani kai raam hvai hai sahaaee | jahaa putr maataa na taataa na bhaaee | 85 |","meaning_en":"","page":2105}]},{"type":"verse","number":[86],"number_text":"੮੬।","page":2105,"lines":[{"gurmukhi":"ਮਹਾ ਕਾਲ ਜੂ ਕੋ ਸਦਾ ਸੀਸ ਨ੍ਯੈਯੈ। ਪੁਰੀ ਚੌਦਹੂੰ ਤ੍ਰਾਸ ਜਾ ਕੋ ਤ੍ਰਸੈਯੈ।","roman":"Mahaa kaal joo ko sadaa sees nyaiyai | puree chaudhoon traas jaa ko trasaiyai |","meaning_en":"","page":2105},{"gurmukhi":"ਸਦਾ ਆਨਿ ਜਾ ਕੀ ਸਭੈ ਜੀਵ ਮਾਨੈ। ਸਭੈ ਲੋਕ ਖ੍ਯਾਤਾ ਬਿਧਾਤਾ ਪਛਾਨੈ। ੮੬।","roman":"Sadaa aani jaa kee sabhai jeev maanai | sabhai lok khyaataa bidhaataa pachhaanai | 86 |","meaning_en":"","page":2105}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":2105,"lines":[{"gurmukhi":"ਨਹੀ ਜਾਨਿ ਜਾਈ ਕਛੂ ਰੂਪ ਰੇਖਾ। ਕਹਾ ਬਾਸ ਤਾ ਕੋ ਫਿਰੈ ਕੌਨ ਭੇਖਾ।","roman":"Nahee jaani jaaee kachhoo roop rekhaa | kahaa baas taa ko phirai kaun bhekhaa |","meaning_en":"","page":2105},{"gurmukhi":"ਕਹਾ ਨਾਮ ਤਾ ਕੋ ਕਹਾ ਕੈ ਕਹਾਵੈ। ਕਹਾ ਕੈ ਬਖਾਨੋ ਕਹੇ ਮੋ ਨ ਆਵੈ। ੮੭।","roman":"Kahaa naam taa ko kahaa kai kahaavai | kahaa kai bakhaano kahe mo na aavai | 87 |","meaning_en":"","page":2105}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":2105,"lines":[{"gurmukhi":"ਨ ਤਾ ਕੋ ਕੋਊ ਤਾਤ ਮਾਤਾ ਨ ਭਾਈ। ਨ ਪੁਤ੍ਰਾ ਨ ਪੋਤ੍ਰਾ ਨ ਦਾਯਾ ਨ ਦਾਈ।","roman":"Na taa ko ko'oo taat maataa na bhaaee | na putraa na potraa na daayaa na daaee |","meaning_en":"","page":2105},{"gurmukhi":"ਕਛੂ ਸੰਗ ਸੈਨਾ ਨ ਤਾ ਕੋ ਸੁਹਾਵੈ। ਕਹੈ ਸਤਿ ਸੋਈ ਕਰੈ ਸੋ ਬਨ੍ਯਾਵੈ। ੮੮।","roman":"Kachhoo sang sainaa na taa ko suhaavai | kahai sati soee karai so banyaavai | 88 |","meaning_en":"","page":2105}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":2105,"lines":[{"gurmukhi":"ਕਈਊ ਸਵਾਰੈ ਕਈਊ ਖਪਾਵੈ। ਉਸਾਰੇ ਗੜੇ ਫੇਰਿ ਮੇਟੈ ਬਨਾਵੈ।","roman":"Kaeeoo savaarai kaeeoo khapaavai | usaare gare pheri metai banaavai |","meaning_en":"","page":2105},{"gurmukhi":"ਘਨੀ ਬਾਰ ਲੌ ਪੰਥ ਚਾਰੋ ਭ੍ਰਮਾਨਾ। ਮਹਾ ਕਾਲ ਹੀ ਕੋ ਗੁਰੂ ਕੈ ਪਛਾਨਾ। ੮੯।","roman":"Ghanee baar lau panth chaaro bhramaanaa | mahaa kaal hee ko guroo kai pachhaanaa | 89 |","meaning_en":"","page":2105}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":2105,"lines":[{"gurmukhi":"ਮੁਰੀਦ ਹੈ ਉਸੀ ਕਾ ਵਹੈ ਪੀਰ ਮੇਰੋ। ਉਸੀ ਕਾ ਕਿਯਾ ਆਪਨਾ ਜੀਵ ਚੇਰੋ।","roman":"Mureed hai usee kaa vahai peer mero | usee kaa kiyaa aapnaa jeev chero |","meaning_en":"","page":2105},{"gurmukhi":"ਤਿਸੀ ਕਾ ਕੀਆ ਬਾਲਕਾ ਮੈ ਕਹਾਵੌ। ਉਹੀ ਮੋਹਿ ਰਾਖਾ ਉਸੀ ਕੋ ਧਿਆਵੌ। ੯੦।","roman":"Tisee kaa keeaa baalkaa mai kahaavau | uhee mohi raakhaa usee ko dhiaavau | 90 |","meaning_en":"","page":2105}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2105},{"type":"verse","number":[91],"number_text":"੯੧।","page":2105,"lines":[{"gurmukhi":"ਦਿਜ ਹਮ ਮਹਾ ਕਾਲ ਕੋ ਮਾਨੈ। ਪਾਹਨ ਮੈ ਮਨ ਕੋ ਨਹਿ ਆਨੈ।","roman":"Dij ham mahaa kaal ko maanai | paahan mai man ko nahi aanai |","meaning_en":"","page":2105},{"gurmukhi":"ਪਾਹਨ ਕੋ ਪਾਹਨ ਕਰਿ ਜਾਨਤ। ਤਾ ਤੇ ਬੁਰੋ ਲੋਗ ਏ ਮਾਨਤ। ੯੧।","roman":"Paahan ko paahan kari jaanat | taa te buro log e maanat | 91 |","meaning_en":"","page":2105}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":2105,"lines":[{"gurmukhi":"ਝੂਠਾ ਕਹ ਝੂਠਾ ਹਮ ਕੈ ਹੈ। ਜੋ ਸਭ ਲੋਗ ਮਨੈ ਕੁਰਰੈ ਹੈ।","roman":"Jhoothaa kah jhoothaa ham kai hai | jo sabh log manai kurrai hai |","meaning_en":"","page":2105},{"gurmukhi":"ਹਮ ਕਾਹੂ ਕੀ ਕਾਨਿ ਨ ਰਾਖੈ। ਸਤਿ ਬਚਨ ਮੁਖ ਊਪਰ ਭਾਖੈ। ੯੨।","roman":"Ham kaahoo kee kaani na raakhai | sati bachan mukh oopar bhaakhai | 92 |","meaning_en":"","page":2105}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":2105,"lines":[{"gurmukhi":"ਸੁਨੁ ਦਿਜ ਤੁਮ ਧਨ ਕੇ ਲਬ ਲਾਗੇ। ਮਾਂਗਤ ਫਿਰਤ ਸਭਨ ਕੇ ਆਗੇ।","roman":"Sunu dij tum dhan ke lab laage | maangat phirat sabhan ke aage |","meaning_en":"","page":2105},{"gurmukhi":"ਆਪਨੇ ਮਨ ਭੀਤਰਿ ਨ ਲਜਾਵਹੁ। ਇਕ ਟਕ ਹ੍ਵੈ ਹਰਿ ਧ੍ਯਾਨ ਨ ਲਾਵਹੁ। ੯੩।","roman":"Aapne man bheetri na lajaavhu | ik tak hvai hari dhyaan na laavhu | 93 |","meaning_en":"","page":2105}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2105},{"type":"verse","number":[94],"number_text":"੯੪।","page":2105,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਬੋਲਾ ਤੈ ਕ੍ਯਾ ਮਾਨੈ। ਸੰਭੂ ਕੋ ਪਾਹਨ ਕਰਿ ਮਾਨੈ।","roman":"Tab dij bolaa tai kyaa maanai | sanbhoo ko paahan kari maanai |","meaning_en":"","page":2105},{"gurmukhi":"ਜੋ ਇਨ ਕੋ ਕਰਿ ਆਨ ਬਖਾਨੈ। ਤਾ ਕੋ ਬ੍ਰਹਮ ਪਾਤਕੀ ਜਾਨੈ। ੯੪।","roman":"Jo in ko kari aan bakhaanai | taa ko braham paatkee jaanai | 94 |","meaning_en":"","page":2105}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":2105,"lines":[{"gurmukhi":"ਜੋ ਇਨ ਕਹ ਕਟੁ ਬਚਨ ਉਚਾਰੈ। ਤਾ ਕੌ ਮਹਾ ਨਰਕ ਬਿਧਿ ਡਾਰੈ।","roman":"Jo in kah katu bachan uchaarai | taa kau mahaa narak bidhi daarai |","meaning_en":"","page":2105},{"gurmukhi":"ਇਨ ਕੀ ਸਦਾ ਕੀਜਿਯੈ ਸੇਵਾ। ਏ ਹੈ ਪਰਮ ਪੁਰਾਤਨ ਦੇਵਾ। ੯੫।","roman":"In kee sadaa keejiyai sevaa | e hai param puraatan devaa | 95 |","meaning_en":"","page":2105}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2107},{"type":"verse","number":[96],"number_text":"੯੬।","page":2107,"lines":[{"gurmukhi":"ਏਕੈ ਮਹਾ ਕਾਲ ਹਮ ਮਾਨੈ। ਮਹਾ ਰੁਦ੍ਰ ਕਹ ਕਛੂ ਨ ਜਾਨੈ।","roman":"Ekai mahaa kaal ham maanai | mahaa rudr kah kachhoo na jaanai |","meaning_en":"","page":2107},{"gurmukhi":"ਬ੍ਰਹਮ ਬਿਸਨ ਕੀ ਸੇਵ ਨ ਕਰਹੀ। ਤਿਨ ਤੇ ਹਮ ਕਬਹੂੰ ਨਹੀ ਡਰਹੀ। ੯੬।","roman":"Braham bisan kee sev na karhee | tin te ham kabhoon nahee darhee | 96 |","meaning_en":"","page":2107}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":2107,"lines":[{"gurmukhi":"ਬ੍ਰਹਮ ਬਿਸਨ ਜਿਨ ਪੁਰਖ ਉਚਾਰਿਯੋ। ਤਾ ਕੌ ਮ੍ਰਿਤੁ ਜਾਨਿਯੈ ਮਾਰਿਯੋ।","roman":"Braham bisan jin purakh uchaariyo | taa kau mritu jaaniyai maariyo |","meaning_en":"","page":2107},{"gurmukhi":"ਜਿਨ ਨਰ ਕਾਲ ਪੁਰਖ ਕੋ ਧ੍ਯਾਯੋ। ਤਾ ਕੇ ਨਿਕਟ ਕਾਲ ਨਹਿ ਆਯੋ। ੯੭।","roman":"Jin nar kaal purakh ko dhyaayo | taa ke nikat kaal nahi aayo | 97 |","meaning_en":"","page":2107}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":2107,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਕਾਲ ਪੁਰਖ ਕੋ ਧ੍ਯਾਵੈ। ਤੇ ਨਰ ਕਾਲ ਫਾਸ ਨਹਿ ਜਾਵੈ।","roman":"Je nar kaal purakh ko dhyaavai | te nar kaal phaas nahi jaavai |","meaning_en":"","page":2107},{"gurmukhi":"ਤਿਨ ਕੇ ਰਿਧ ਸਿਧ ਸਭ ਘਰ ਮੌ। ਕੋਬਿਦ ਸਭ ਹੀ ਰਹਤ ਹੁਨਰ ਮੌ। ੯੮।","roman":"Tin ke ridh sidh sabh ghar mau | kobid sabh hee rahat hunar mau | 98 |","meaning_en":"","page":2107}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":2107,"lines":[{"gurmukhi":"ਕਾਲ ਪੁਰਖ ਇਕਦਾ ਜਿਨ ਕਹਾ। ਤਾ ਕੇ ਰਿਧਿ ਸਿਧਿ ਹ੍ਵੈ ਰਹਾ।","roman":"Kaal purakh ikdaa jin kahaa | taa ke ridhi sidhi hvai rahaa |","meaning_en":"","page":2107},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਧਨ ਭਰੇ ਭੰਡਾਰੂ। ਜਿਨ ਕਾ ਆਵਤ ਵਾਰ ਨ ਪਾਰੂ। ੯੯।","roman":"Bhaati bhaati dhan bhare bhandaaroo | jin kaa aavat vaar na paaroo | 99 |","meaning_en":"","page":2107}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":2107,"lines":[{"gurmukhi":"ਜਿਨ ਨਰ ਕਾਲ ਪੁਰਖ ਕਹ ਧ੍ਯਾਯੋ। ਸੋ ਨਰ ਕਲਿ ਮੋ ਕਬਹੂ ਨ ਆਯੋ।","roman":"Jin nar kaal purakh kah dhyaayo | so nar kali mo kabhoo na aayo |","meaning_en":"","page":2107},{"gurmukhi":"ਯਾ ਜਗ ਮੈ ਤੇ ਅਤਿ ਸੁਖ ਪਾਵੈ। ਭੋਗ ਕਰੈ ਬੈਰਨਿ ਕਹ ਘਾਵੈ। ੧੦੦।","roman":"Yaa jag mai te ati sukh paavai | bhog karai bairni kah ghaavai | 100 |","meaning_en":"","page":2107}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":2107,"lines":[{"gurmukhi":"ਜਬ ਤੋ ਕੋ ਦਿਜ ਕਾਲ ਸਤੈ ਹੈ। ਤਬ ਤੂ ਕੋ ਪੁਸਤਕ ਕਰ ਲੈ ਹੈ।","roman":"Jab to ko dij kaal satai hai | tab too ko pustak kar lai hai |","meaning_en":"","page":2107},{"gurmukhi":"ਭਾਗਵਤ ਪੜੋ ਕਿ ਗੀਤਾ ਕਹਿ ਹੋ। ਰਾਮਹਿ ਪਕਰਿ ਕਿ ਸਿਵ ਕਹ ਗਹਿ ਹੋ। ੧੦੧।","roman":"Bhaagvat paro ki geetaa kahi ho | raamhi pakri ki siv kah gahi ho | 101 |","meaning_en":"","page":2107}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":2107,"lines":[{"gurmukhi":"ਜੇ ਤੁਮ ਪਰਮ ਪੁਰਖ ਠਹਰਾਏ। ਤੇ ਸਭ ਡੰਡ ਕਾਲ ਕੇ ਘਾਏ।","roman":"Je tum param purakh thahraae | te sabh dand kaal ke ghaae |","meaning_en":"","page":2107},{"gurmukhi":"ਕਾਲ ਡੰਡ ਬਿਨ ਬਚਾ ਨ ਕੋਈ। ਸਿਵ ਬਿਰੰਚ ਬਿਸਨਿੰਦ੍ਰ ਨ ਸੋਈ। ੧੦੨।","roman":"Kaal dand bin bachaa na koee | siv biranch bisnindr na soee | 102 |","meaning_en":"","page":2107}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":2107,"lines":[{"gurmukhi":"ਜੈਸਿ ਜੂਨਿ ਇਕ ਦੈਤ ਬਖਨਿਯਤ। ਤ੍ਯੋ ਇਕ ਜੂਨਿ ਦੇਵਤਾ ਜਨਿਯਤ।","roman":"Jaisi jooni ik dait bakhniyat | tyo ik jooni devtaa janiyat |","meaning_en":"","page":2107},{"gurmukhi":"ਜੈਸੇ ਹਿੰਦੂਆਨੋ ਤੁਰਕਾਨਾ। ਸਭਹਿੰਨ ਸੀਸ ਕਾਲ ਜਰਵਾਨਾ। ੧੦੩।","roman":"Jaise hindooaano turkaanaa | sabhhinn sees kaal jarvaanaa | 103 |","meaning_en":"","page":2107}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":2107,"lines":[{"gurmukhi":"ਕਬਹੂੰ ਦੈਤ ਦੇਵਤਨ ਮਾਰੈ। ਕਬਹੂੰ ਦੈਤਨ ਦੇਵ ਸੰਘਾਰੈ।","roman":"Kabhoon dait devtan maarai | kabhoon daitan dev sanghaarai |","meaning_en":"","page":2107},{"gurmukhi":"ਦੇਵ ਦੈਤ ਜਿਨ ਦੋਊ ਸੰਘਾਰਾ। ਵਹੈ ਪੁਰਖ ਪ੍ਰਤਿਪਾਲ ਹਮਾਰਾ। ੧੦੪।","roman":"Dev dait jin do'oo sanghaaraa | vahai purakh pratipaal hamaaraa | 104 |","meaning_en":"","page":2107}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2107},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":2107,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਉਪਿੰਦ੍ਰ ਦਿਨਿੰਦ੍ਰਹਿ ਜੌਨ ਸੰਘਾਰਿਯੋ।","roman":"Indr upindr dinindrahi jaun sanghaariyo |","meaning_en":"","page":2107},{"gurmukhi":"ਚੰਦ੍ਰ ਕੁਬੇਰ ਜਲਿੰਦ੍ਰ ਅਹਿੰਦ੍ਰਹਿ ਮਾਰਿਯੋ।","roman":"Chandr kuber jalindr ahindrahi maariyo |","meaning_en":"","page":2107},{"gurmukhi":"ਪੁਰੀ ਚੌਦਹੂੰ ਚਕ੍ਰ ਜਵਨ ਸੁਨਿ ਲੀਜਿਯੈ।","roman":"Puree chaudhoon chakr javan suni leejiyai |","meaning_en":"","page":2107},{"gurmukhi":"ਹੋ ਨਮਸਕਾਰ ਤਾਹੀ ਕੋ ਗੁਰ ਕਰਿ ਕੀਜਿਯੈ। ੧੦੫।","roman":"Ho namaskaar taahee ko gur kari keejiyai | 105 |","meaning_en":"","page":2107}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2109},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2109},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":2109,"lines":[{"gurmukhi":"ਬਹੁ ਬਿਧਿ ਬਿਪ੍ਰਹਿ ਕੋ ਸਮਝਾਯੋ। ਪੁਨਿ ਮਿਸ੍ਰਹਿ ਅਸ ਭਾਖਿ ਸੁਨਾਯੋ।","roman":"Bahu bidhi biprahi ko samjhaayo | puni misrahi as bhaakhi sunaayo |","meaning_en":"","page":2109},{"gurmukhi":"ਜੇ ਪਾਹਨ ਕੀ ਪੂਜਾ ਕਰਿ ਹੈ। ਤਾ ਕੇ ਪਾਪ ਸਕਲ ਸਿਵ ਹਰਿ ਹੈ। ੧੦੬।","roman":"Je paahan kee poojaa kari hai | taa ke paap sakal siv hari hai | 106 |","meaning_en":"","page":2109}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":2109,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਸਾਲਿਗ੍ਰਾਮ ਕਹ ਧਯੈ ਹੈ। ਤਾ ਕੇ ਸਕਲ ਪਾਪ ਕੋ ਛੈ ਹੈ।","roman":"Je nar saaligraam kah dhayai hai | taa ke sakal paap ko chhai hai |","meaning_en":"","page":2109},{"gurmukhi":"ਜੋ ਇਹ ਛਾਡਿ ਅਵਰ ਕਹ ਧਯੈ ਹੈ। ਤੇ ਨਰ ਮਹਾ ਨਰਕ ਮਹਿ ਜੈ ਹੈ। ੧੦੭।","roman":"Jo ih chhaadi avar kah dhayai hai | te nar mahaa narak mahi jai hai | 107 |","meaning_en":"","page":2109}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":2109,"lines":[{"gurmukhi":"ਜੇ ਨਰ ਕਛੁ ਧਨ ਬਿਪ੍ਰਹਿ ਦੈ ਹੈ। ਆਗੇ ਮਾਗ ਦਸ ਗੁਨੋ ਲੈਹੈ।","roman":"Je nar kachhu dhan biprahi dai hai | aage maag das guno laihai |","meaning_en":"","page":2109},{"gurmukhi":"ਜੋ ਬਿਪ੍ਰਨ ਬਿਨੁ ਅਨਤੈ ਦੇਹੀ। ਤਾ ਕੌ ਕਛੁ ਸੁ ਫਲੈ ਨਹਿ ਸੇਈ। ੧੦੮।","roman":"Jo bipran binu antai dehee | taa kau kachhu su phalai nahi se'ee | 108 |","meaning_en":"","page":2109}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":2109},{"type":"verse","number":[109],"number_text":"੧੦੯।","page":2109,"lines":[{"gurmukhi":"ਤਬੈ ਕੁਅਰਿ ਪ੍ਰਤਿਮਾ ਸਿਵ ਕੀ ਕਰ ਮੈ ਲਈ।","roman":"Tabai kuari pratimaa siv kee kar mai laee |","meaning_en":"","page":2109},{"gurmukhi":"ਹਸਿ ਹਸਿ ਕਰਿ ਦਿਜ ਕੇ ਮੁਖ ਕਸਿ ਕਸਿ ਕੈ ਦਈ।","roman":"Hasi hasi kari dij ke mukh kasi kasi kai daee |","meaning_en":"","page":2109},{"gurmukhi":"ਸਾਲਿਗ੍ਰਾਮ ਭੇ ਦਾਂਤਿ ਫੋਰਿ ਸਭ ਹੀ ਦੀਏ।","roman":"Saaligraam bhe daanti phori sabh hee dee'e |","meaning_en":"","page":2109},{"gurmukhi":"ਹੋ ਛੀਨਿ ਛਾਨਿ ਕਰਿ ਬਸਤ੍ਰ ਮਿਸ੍ਰ ਕੇ ਸਭ ਲੀਏ। ੧੦੯।","roman":"Ho chheeni chhaani kari basatr misr ke sabh lee'e | 109 |","meaning_en":"","page":2109}]},{"type":"verse","number":[110],"number_text":"੧੧੦।","page":2109,"lines":[{"gurmukhi":"ਕਹੋ ਮਿਸ੍ਰ ਅਬ ਰੁਦ੍ਰ ਤਿਹਾਰੋ ਕਹ ਗਯੋ।","roman":"Kaho misr ab rudr tihaaro kah gayo |","meaning_en":"","page":2109},{"gurmukhi":"ਜਿਹ ਸੇਵਤ ਥੋ ਸਦਾ ਦਾਂਤਿ ਛੈ ਤਿਨ ਕਿਯੋ।","roman":"Jih sevat tho sadaa daanti chhai tin kiyo |","meaning_en":"","page":2109},{"gurmukhi":"ਜਿਹ ਲਿੰਗਹਿ ਕੌ ਜਪਤੇ ਕਾਲ ਬਤਾਇਯੋ।","roman":"Jih linghi kau japte kaal bataaiyo |","meaning_en":"","page":2109},{"gurmukhi":"ਹੋ ਅੰਤ ਕਾਲ ਸੋ ਤੁਮਰੇ ਮੁਖ ਮਹਿ ਆਇਯੋ। ੧੧੦।","roman":"Ho ant kaal so tumre mukh mahi aaiyo | 110 |","meaning_en":"","page":2109}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2109},{"type":"verse","number":[111],"number_text":"੧੧੧।","page":2109,"lines":[{"gurmukhi":"ਤਾ ਕੋ ਦਰਬੁ ਛੀਨਿ ਜੋ ਲਿਯੋ। ਜੋ ਸਭ ਦਾਨ ਦਿਜਨ ਕਰਿ ਦਿਯੋ।","roman":"Taa ko darbu chheeni jo liyo | jo sabh daan dijan kari diyo |","meaning_en":"","page":2109},{"gurmukhi":"ਕਹਿਯੋ ਮਿਸ੍ਰ ਕਛੁ ਚਿੰਤ ਨ ਕਰਹੂੰ। ਦਾਨ ਦਸ ਗੁਨੋ ਅਗੈ ਫਰਹੂੰ। ੧੧੧।","roman":"Kahiyo misr kachhu chint na karhoon | daan das guno agai pharhoon | 111 |","meaning_en":"","page":2109}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":2109},{"type":"verse","number":[112],"number_text":"੧੧੨।","page":2109,"lines":[{"gurmukhi":"ਔਰਨ ਕੋ ਕਹਤ ਲੁਟਾਵੋ ਤੁਮ ਖਾਹੁ ਧਨ ਆਪੁ","roman":"Auran ko kahat lutaavo tum khaahu dhan aapu","meaning_en":"","page":2109},{"gurmukhi":"ਪਹਿਤੀ ਮੈ ਡਾਰਿ ਖਾਤ ਨ ਬਿਸਾਰ ਹੈਂ।","roman":"Pahitee mai daari khaat na bisaar hain |","meaning_en":"","page":2109},{"gurmukhi":"ਬਡੇ ਹੀ ਪ੍ਰਪੰਚੀ ਪਰਪਚੰਨ ਕੋ ਲੀਏ ਫਿਰੈ","roman":"Bade hee prapanchee parapchann ko lee'e phirai","meaning_en":"","page":2109},{"gurmukhi":"ਦਿਨ ਹੀ ਮੈ ਲੋਗਨ ਕੋ ਲੂਟਤ ਬਜਾਰ ਹੈਂ।","roman":"Din hee mai logan ko lootat bajaar hain |","meaning_en":"","page":2109},{"gurmukhi":"ਹਾਥ ਤੇ ਨ ਕੌਡੀ ਦੇਤ ਕੌਡੀ ਕੌਡੀ ਮਾਂਗ ਲੇਤ","roman":"Haath te na kaudee det kaudee kaudee maang let","meaning_en":"","page":2109},{"gurmukhi":"ਪੁਤ੍ਰੀ ਕਹਤ ਤਾ ਸੋ ਕਰੈ ਬਿਭਚਾਰ ਹੈਂ।","roman":"Putree kahat taa so karai bibhchaar hain |","meaning_en":"","page":2109},{"gurmukhi":"ਲੋਭਤਾ ਕੇ ਜਏ ਹੈਂ ਕਿ ਮਮਤਾ ਕੇ ਭਏ ਹੈਂ","roman":"Lobhtaa ke jae hain ki mamtaa ke bhae hain","meaning_en":"","page":2109},{"gurmukhi":"ਏ ਸੂਮਤਾ ਕੇ ਪੁਤ੍ਰ ਕੈਧੌ ਦਰਿਦ੍ਰਾਵਤਾਰ ਹੈਂ। ੧੧੨।","roman":"E soomtaa ke putr kaidhau daridraavtaar hain | 112 |","meaning_en":"","page":2109}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2111},{"type":"verse","number":[113],"number_text":"੧੧੩।","page":2111,"lines":[{"gurmukhi":"ਪਹਤੀ ਬਿਖੈ ਬਿਸਾਰ ਨ ਡਾਰਹਿ। ਔਰਨ ਪਾਸ ਗਾਲ ਕੋ ਮਾਰਹਿ।","roman":"Pahtee bikhai bisaar na daarhi | auran paas gaal ko maarhi |","meaning_en":"","page":2111},{"gurmukhi":"ਜਨਿਯਤ ਕਿਸੀ ਦੇਸ ਕੇ ਰਾਜਾ। ਕੌਡੀ ਕੇ ਆਵਤ ਨਹਿ ਕਾਜਾ। ੧੧੩।","roman":"Janiyat kisee des ke raajaa | kaudee ke aavat nahi kaajaa | 113 |","meaning_en":"","page":2111}]},{"type":"verse","number":[114],"number_text":"੧੧੪।","page":2111,"lines":[{"gurmukhi":"ਜੌ ਇਨ ਮੰਤ੍ਰ ਜੰਤ੍ਰ ਸਿਧਿ ਹੋਈ। ਦਰ ਦਰ ਭੀਖਿ ਨ ਮਾਂਗੈ ਕੋਈ।","roman":"Jau in mantr jantr sidhi hoee | dar dar bheekhi na maangai koee |","meaning_en":"","page":2111},{"gurmukhi":"ਏਕੈ ਮੁਖ ਤੇ ਮੰਤ੍ਰ ਉਚਾਰੈ। ਧਨ ਸੌ ਸਕਲ ਧਾਮ ਭਰਿ ਡਾਰੈ। ੧੧੪।","roman":"Ekai mukh te mantr uchaarai | dhan sau sakal dhaam bhari daarai | 114 |","meaning_en":"","page":2111}]},{"type":"verse","number":[115],"number_text":"੧੧੫।","page":2111,"lines":[{"gurmukhi":"ਰਾਮ ਕ੍ਰਿਸਨ ਏ ਜਿਨੈ ਬਖਾਨੈ। ਸਿਵ ਬ੍ਰਹਮਾ ਏ ਜਾਹਿ ਪ੍ਰਮਾਨੈ।","roman":"Raam krisan e jinai bakhaanai | siv brahmaa e jaahi pramaanai |","meaning_en":"","page":2111},{"gurmukhi":"ਤੇ ਸਭ ਹੀ ਸ੍ਰੀ ਕਾਲ ਸੰਘਾਰੇ। ਕਾਲ ਪਾਇ ਕੈ ਬਹੁਰਿ ਸਵਾਰੇ। ੧੧੫।","roman":"Te sabh hee sree kaal sanghaare | kaal paai kai bahuri savaare | 115 |","meaning_en":"","page":2111}]},{"type":"verse","number":[116],"number_text":"੧੧੬।","page":2111,"lines":[{"gurmukhi":"ਕੇਤੇ ਰਾਮਚੰਦ ਅਰੁ ਕ੍ਰਿਸਨਾ। ਕੇਤੇ ਚਤੁਰਾਨਨ ਸਿਵ ਬਿਸਨਾ।","roman":"Kete raamchand aru krisnaa | kete chaturaanan siv bisnaa |","meaning_en":"","page":2111},{"gurmukhi":"ਚੰਦ ਸੂਰਜ ਏ ਕਵਨ ਬਿਚਾਰੇ। ਪਾਨੀ ਭਰਤ ਕਾਲ ਕੇ ਦ੍ਵਾਰੇ। ੧੧੬।","roman":"Chand sooraj e kavan bichaare | paanee bharat kaal ke dvaare | 116 |","meaning_en":"","page":2111}]},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":2111,"lines":[{"gurmukhi":"ਕਾਲ ਪਾਇ ਸਭ ਹੀ ਏ ਭਏ। ਕਾਲੋ ਪਾਇ ਕਾਲ ਹ੍ਵੈ ਗਏ।","roman":"Kaal paai sabh hee e bhae | kaalo paai kaal hvai gae |","meaning_en":"","page":2111},{"gurmukhi":"ਕਾਲਹਿ ਪਾਇ ਬਹੁਰਿ ਅਵਤਰਿ ਹੈ। ਕਾਲਹਿ ਕਾਲ ਪਾਇ ਸੰਘਰਿ ਹੈ। ੧੧੭।","roman":"Kaalhi paai bahuri avatri hai | kaalhi kaal paai sanghri hai | 117 |","meaning_en":"","page":2111}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2111},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":2111,"lines":[{"gurmukhi":"ਸ੍ਰਾਪ ਰਾਛਸੀ ਕੇ ਦਏ ਜੋ ਭਯੋ ਪਾਹਨ ਜਾਇ।","roman":"Sraap raachhsee ke dae jo bhayo paahan jaai |","meaning_en":"","page":2111},{"gurmukhi":"ਤਾਹਿ ਕਹਤ ਪਰਮੇਸ੍ਰ ਤੈ ਮਨ ਮਹਿ ਨਹੀ ਲਜਾਇ। ੧੧੮।","roman":"Taahi kahat parmesr tai man mahi nahee lajaai | 118 |","meaning_en":"","page":2111}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2111},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":2111},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":2111,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਅਧਿਕ ਕੋਪ ਹ੍ਵੈ ਗਯੋ। ਭਰਭਰਾਇ ਠਾਢਾ ਉਠਿ ਭਯੋ।","roman":"Tab dij adhik kop hvai gayo | bharabhraai thaadhaa uthi bhayo |","meaning_en":"","page":2111},{"gurmukhi":"ਅਬ ਮੈ ਇਹ ਰਾਜਾ ਪੈ ਜੈਹੌ। ਤਹੀ ਬਾਂਧਿ ਕਰਿ ਤੋਹਿ ਮੰਗੈ ਹੌ। ੧੧੯।","roman":"Ab mai ih raajaa pai jaihau | tahee baandhi kari tohi mangai hau | 119 |","meaning_en":"","page":2111}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2111},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":2111,"lines":[{"gurmukhi":"ਤਬ ਤਿਨ ਕੁਅਰਿ ਦਿਜਹਿ ਗਹਿ ਲਿਆ। ਡਾਰ ਨਦੀ ਕੇ ਭੀਤਰ ਦਿਯਾ।","roman":"Tab tin kuari dijhi gahi liaa | daar nadee ke bheetar diyaa |","meaning_en":"","page":2111},{"gurmukhi":"ਗੋਤਾ ਪਕਰਿ ਆਠ ਸੈ ਦੀਨਾ। ਤਾਹਿ ਪਵਿਤ੍ਰ ਭਲੀ ਬਿਧਿ ਕੀਨਾ। ੧੨੦।","roman":"Gotaa pakri aath sai deenaa | taahi pavitr bhalee bidhi keenaa | 120 |","meaning_en":"","page":2111}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":2111,"lines":[{"gurmukhi":"ਕਹੀ ਕੁਅਰਿ ਪਿਤੁ ਪਹਿ ਮੈ ਜੈ ਹੌ। ਤੈ ਮੁਹਿ ਡਾਰਾ ਹਾਥ ਬਤੈ ਹੌ।","roman":"Kahee kuari pitu pahi mai jai hau | tai muhi daaraa haath batai hau |","meaning_en":"","page":2111},{"gurmukhi":"ਤੇਰੇ ਦੋਨੋ ਹਾਥ ਕਟਾਊ। ਤੌ ਰਾਜਾ ਕੀ ਸੁਤਾ ਕਹਾਊ। ੧੨੧।","roman":"Tere dono haath kataaoo | tau raajaa kee sutaa kahaaoo | 121 |","meaning_en":"","page":2111}]},{"type":"heading","kind":"speaker","name":"ਦਿਜ ਬਾਚ","gurmukhi":"ਦਿਜ ਬਾਚ","roman":"Dij baach","meaning_en":"","page":2111},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":2111,"lines":[{"gurmukhi":"ਇਹ ਸੁਨਿ ਬਾਤ ਮਿਸ੍ਰ ਡਰ ਪਯੋ। ਲਾਗਤ ਪਾਇ ਕੁਅਰਿ ਕੇ ਭਯੋ।","roman":"Ih suni baat misr dar payo | laagat paai kuari ke bhayo |","meaning_en":"","page":2111},{"gurmukhi":"ਸੋਊ ਕਰੋ ਜੁ ਮੋਹਿ ਉਚਾਰੋ। ਤੁਮ ਨਿਜੁ ਜਿਯ ਤੇ ਕੋਪ ਨਿਵਾਰੋ। ੧੨੨।","roman":"So'oo karo ju mohi uchaaro | tum niju jiy te kop nivaaro | 122 |","meaning_en":"","page":2111}]},{"type":"heading","kind":"speaker","name":"ਕੁਅਰਿ ਬਾਚ","gurmukhi":"ਕੁਅਰਿ ਬਾਚ","roman":"Kuari baach","meaning_en":"","page":2113},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":2113,"lines":[{"gurmukhi":"ਤੁਮ ਕਹਿਯਹੁ ਮੈ ਪ੍ਰਥਮ ਅਨਾਯੋ। ਧਨ ਨਿਮਿਤਿ ਮੈ ਦਰਬੁ ਲੁਟਾਯੋ।","roman":"Tum kahiyhu mai pratham anaayo | dhan nimiti mai darbu lutaayo |","meaning_en":"","page":2113},{"gurmukhi":"ਪਾਹਨ ਕੀ ਪੂਜਾ ਨਹਿ ਕਰਿਯੈ। ਮਹਾ ਕਾਲ ਕੇ ਪਾਇਨ ਪਰਿਯੈ। ੧੨੩।","roman":"Paahan kee poojaa nahi kariyai | mahaa kaal ke paain pariyai | 123 |","meaning_en":"","page":2113}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":2113},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":2113,"lines":[{"gurmukhi":"ਤਬ ਦਿਜ ਮਹਾ ਕਾਲ ਕੋ ਧ੍ਯਾਯੋ। ਸਰਿਤਾ ਮਹਿ ਪਾਹਨਨ ਬਹਾਯੋ।","roman":"Tab dij mahaa kaal ko dhyaayo | saritaa mahi paahnan bahaayo |","meaning_en":"","page":2113},{"gurmukhi":"ਦੂਜੇ ਕਾਨ ਨ ਕਿਨਹੂੰ ਜਾਨਾ। ਕਹਾ ਮਿਸ੍ਰ ਪਰ ਹਾਲ ਬਿਹਾਨਾ। ੧੨੪।","roman":"Dooje kaan na kinhoon jaanaa | kahaa misr par haal bihaanaa | 124 |","meaning_en":"","page":2113}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":2113},{"type":"verse","number":[125,1],"number_text":"੧੨੫। ੧।","page":2113,"lines":[{"gurmukhi":"ਇਹ ਛਲ ਸੌ ਮਿਸਰਹਿ ਛਲਾ ਪਾਹਨ ਦਏ ਬਹਾਇ।","roman":"Ih chhal sau misarhi chhalaa paahan dae bahaai |","meaning_en":"","page":2113},{"gurmukhi":"ਮਹਾ ਕਾਲ ਕੋ ਸਿਖ੍ਯ ਕਰਿ ਮਦਰਾ ਭਾਂਗ ਪਿਵਾਇ। ੧੨੫। ੧।","roman":"Mahaa kaal ko sikhy kari madraa bhaang pivaai | 125 | 1 |","meaning_en":"","page":2113}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋਇ ਸੌ ਛਿਆਸਠਿ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade doi sau chhiaasthi charitr samaaptam","meaning_en":"","page":2113},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੬੬। ੫੧੯੫। ਅਫਜੂੰ।","roman":"Satu subham satu | 266 | 5195 | aphjoon |","meaning_en":"","page":2113}],"page":2113,"number":[266,5195]}});
